			function emaildatareplace($data, $mesg){
				global $callConfig;
				$mes1= strpos($mesg,'{[')+2;
				$mes2= strpos($mesg,']}');
				if($mes2 == ''){ $mes2=0; }
				if($mes1>0 && $mes2>0){
					$str =''; $sstr ='';
					$str = strtolower(substr($mesg,$mes1,$mes2-$mes1));
					$sstr = "{[".$str."]}";
					$mesg = str_replace($sstr, $data[$str], $mesg);
					$mesg = $this->emaildatareplace($data, $mesg);
				} 

				return $mesg;
			}
			function emailnumberschange($mesg){
				global $callConfig;
				$mes1= strpos($mesg,'[')+1;
				$mes2= strpos($mesg,']');
				if($mes2 == ''){ $mes2=0; }
		//echo "11qww".$mes1."ppp".$mes2;
				if($mes1>0 && $mes2>0){
					$str =''; $sstr ='';
					$str = substr($mesg,$mes1,$mes2-$mes1);
					$sstr = "[".$str."]";
					$mesg = str_replace($sstr, $this->numberToWordFormateRupees($str), $mesg);
					$mesg = $this->emaildatareplace($data, $mesg);	
				} 
				return $mesg;
			}
			function numberToWordFormateRupees($number){
				global $callConfig;
				$no = floor($number);
				$point = round($number - $no, 2) * 100;
				$hundred = null;
				$digits_1 = strlen($no);
				$i = 0;
				$str = array();
				$words = array('0' => '', '1' => 'one', '2' => 'two',
					'3' => 'three', '4' => 'four', '5' => 'five', '6' => 'six',
					'7' => 'seven', '8' => 'eight', '9' => 'nine',
					'10' => 'ten', '11' => 'eleven', '12' => 'twelve',
					'13' => 'thirteen', '14' => 'fourteen',
					'15' => 'fifteen', '16' => 'sixteen', '17' => 'seventeen',
					'18' => 'eighteen', '19' =>'nineteen', '20' => 'twenty',
					'30' => 'thirty', '40' => 'forty', '50' => 'fifty',
					'60' => 'sixty', '70' => 'seventy',
					'80' => 'eighty', '90' => 'ninety');
				$digits = array('', 'hundred', 'thousand', 'lakh', 'crore');
				while ($i < $digits_1) {
					$divider = ($i == 2) ? 10 : 100;
					$number = floor($no % $divider);
					$no = floor($no / $divider);
					$i += ($divider == 10) ? 1 : 2;
					if ($number) {
						$plural = (($counter = count($str)) && $number > 9) ? 's' : null;
						$hundred = ($counter == 1 && $str[0]) ? ' and ' : null;
						$str [] = ($number < 21) ? $words[$number] .
						" " . $digits[$counter] . $plural . " " . $hundred
						:
						$words[floor($number / 10) * 10]
						. " " . $words[$number % 10] . " "
						. $digits[$counter] . $plural . " " . $hundred;
					} else $str[] = null;
				}
				$str = array_reverse($str);
				$result = implode('', $str);
				$points = ($point) ?
				". " . $words[$point / 10] . " " . 
				$words[$point = $point % 10] : '';
				if($result !=''){
					$result = $result . "Rupees  ";
				}
				if($points !=''){
					$result.= $points . " Paise  ";
				}
				return ucwords($result." only");
			}
