	$whr1="company_id= '".$post['company_id']."' and status_progress_id='".$post['status_progress']."'";
	$query2 = $callConfig->selectQuery('status_progress_actions','*',$whr1,'','','');
		//echo $query2; exit;
	$progress = $callConfig->getAllRows($query2);
		//print_r($progress);
	$statuaction= array(); $rechack= array();
	foreach ($progress as $progres) {
		$statuaction[] = $progres->target_status;
	}
		//print_r($statuaction); //exit;
	foreach ($post['target'] as $target) {
		if(in_array($target, $statuaction)){
			$update = "update status_progress_actions set is_active = 0,email_groups='".$post['email_groups']."',notify_users='".$post['notify_users']."',work_flow_field= '".$post['work_flow_field']."' where status_progress_id ='".$post['status_progress']."' and target_status = '".$target."'";
			$update_data=$callConfig->executeQuery($update);
		}else{
			$insert_filed = array('company_id'=>$post['company_id'],'status_progress_id'=>$post['status_progress'],'target_status'=>$target,'email_groups'=>$post['email_groups'],'email_template_id'=>3,'work_flow_field'=>$post['work_flow_field'],'notify_users'=>$post['notify_users'],'current_status'=>$post['current_status'],'status_date'=>$post['status_date'],'from_date'=>$post['from_date'],'to_date'=>$post['to_date'],'created_date'=>$post['created_date'],'created_by'=>$post['created_by'],'is_active'=>'0'); 
				//print_r($insert_filed); exit;
			$insert_data=$callConfig->insertRecord('status_progress_actions',$insert_filed);
		}
		$rechack[] = $target;
	}
	$chek = implode(',', $rechack);
	$lupdate = "update status_progress_actions set is_active = 1 where status_progress_id ='".$post['status_progress']."' and target_status not in (".$chek.")";
	$update_data=$callConfig->executeQuery($lupdate);
		//exit;
	return $update_data;
}
