function holdpayroll_exclusions($post,$get){
	global $callConfig;
    	//print_r($post); echo "ravi"; exit;
	$hquery = $callConfig->selectQuery('payroll_exclusions','id,is_active','emp_id='.$post['emp_id'].' AND pay_year='.$post['pay_year'].' AND category_id ='.$post['category_id'].' AND pay_month='.$post['pay_month'],'','','');
    	//echo $hquery;
	$hudata = $callConfig->getRow($hquery);
	if($hudata->id !=""){ 
		$is_active = $hudata->is_active !=0 ? 0 :1;
		$res=$callConfig->updateRecord('payroll_exclusions', array('is_active'=>$is_active),'id',$hudata->id);
