			$birthday_list_query = "SELECT emp.date_of_birth,emp.display_name,emp.id,emp.image,(SELECT count(id) as cnt FROM `feeds` WHERE msg_type='1' AND birthday_anniversary_type = '1' AND receiving_emp_id=emp.id AND year='".date('Y')."' AND is_active=emp.is_active AND  company_id = emp.company_id) as cnt_commnets,(SELECT count(id) as cnt FROM `feeds` WHERE like_type='1' AND birthday_anniversary_type = '1' AND receiving_emp_id=emp.id AND year='".date('Y')."' AND is_active=emp.is_active AND  company_id = emp.company_id) as cnt_like FROM `employees` emp WHERE emp.company_id='".$company_id."' AND  emp.is_active='0' AND month(emp.date_of_birth) = month(now())";
			
			$birth_list = $callConfig->getAllRows($birthday_list_query);
			//echo "ddd"."<pre>"; print_r($department_list); exit;
			
			foreach ($birth_list as $dob) {
				$emp_data['date_of_birth'] = $dob->date_of_birth;
				$emp_data['display_name'] = $dob->display_name;
				//$emp_data['wedding_date'] = $dob->wedding_date;
				$emp_data['id'] = $dob->id;
				$emp_data['image'] = $dob->image;
				$emp_data['cnt_commnets'] = $dob->cnt_commnets;
				$emp_data['cnt_like'] = $dob->cnt_like;
				$emp_data['sql'] =$birthday_list_query;
				$emplist[] = $emp_data;
				
			}


	//$wedding_list_query = "SELECT * FROM `employees` WHERE WEEK(NOW()) = WEEK( wedding_date + INTERVAL (YEAR(NOW()) - YEAR(wedding_date)) YEAR ) and company_id='".$company_id."' and is_active='0'";
	
	$wedding_list_query = "SELECT emp.wedding_date,emp.display_name,emp.id,emp.image,(SELECT count(id) as cnt FROM `feeds` WHERE msg_type='1' AND birthday_anniversary_type = '2' AND receiving_emp_id=emp.id AND year='".date('Y')."' AND is_active=emp.is_active AND  company_id = emp.company_id) as cnt_commnets,(SELECT count(id) as cnt FROM `feeds` WHERE like_type='1' AND birthday_anniversary_type = '2' AND receiving_emp_id=emp.id AND year='".date('Y')."' AND is_active=emp.is_active AND  company_id = emp.company_id) as cnt_like FROM `employees` emp WHERE emp.company_id='".$company_id."' AND  emp.is_active='0' AND month(emp.wedding_date) = month(now())";
			
	$wed_list = $callConfig->getAllRows($wedding_list_query);

	foreach ($wed_list as $wed) {
		$wed_data['display_name'] = $wed->display_name;
		$wed_data['id'] = $wed->id;
		$wed_data['wedding_date'] = $wed->wedding_date;
		$wed_data['image'] = $wed->image;
		$wed_data['cnt_commnets'] = $wed->cnt_commnets;
		$wed_data['cnt_like'] = $wed->cnt_like;
		$wed_data['sql'] =$wedding_list_query;
		$wedlist[] = $wed_data;
	}


	$return_details['emp_dob_details'] = $emplist;
	$return_details['emp_wed_details'] = $wedlist;
	return $kpi_task_return = $return_details;
}
