function gettasksdetails($get) {
	global $callConfig;
	$company_id = $get['company_id'];
	$filter_id = $get['filter_id'];
	$filter_table = $get['filter_table'];

	/* return buddy_list : from : general_code_details */
	$display_data = "select * from general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='EMPLOYEEBUDDIES' order by id ASC"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['buddy_list'] = $display_details;	


	/* return filter_list : from : general_code_details */
	$display_data = "select * from general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='FILTEROPTIONS'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['filter_list'] = $display_details;	

	/* return filter_list : from : general_code_details */
	$display_data = "select * from application_filters where is_active='0' and company_id='".$company_id."' AND apply_table_name ='onboarding'  AND application_tablename='".$filter_table."'" ; 
//echo $display_data; exit;
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['filter_option'] = $display_details;	


	/* return due_list : from : general_code_details */
	$display_data = "select * from general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='DUEDATETYPES'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['due_list'] = $display_details;	


	/* return period_list : from : general_code_details */
	$display_data = "select * from general_code_details where is_active='0' and company_id='".$company_id."' and genc_code='DUEDATEPERIODS'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['period_list'] = $display_details;	


	/* return emp_list : from : employees */
	$display_data = "select * from employees where is_active='0' and company_id='".$company_id."'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['emp_list'] = $display_details;	


	/* return due_list : from : general_code_details */
	$display_data = "select * from tasks_categories where is_active='0' and company_id='".$company_id."'"; 
	$display_details = $callConfig->getAllRows($display_data);
	$task_details['task_list'] = $display_details;	

	if($filter_id != ""){
		$filterurl = "select * from filter_tables where is_active='0' and company_id='".$company_id."' AND transaction_id='".$filter_id."'"; 
		$filterdetails = $callConfig->getRow($filterurl);
		$task_details['filter_data'] = $filterdetails;
	}

	return $task_details;
}



