    function togetnoteslist($get) {
    	global $callConfig;
    	$company_id = $get['company_id'];
    	$offset_limit = $get['offset_limit'];
    	$no_of_records_per_page = $get['no_of_records_per_page']; 
    	$selected_notes = $get['selected_notes'];
    	$note_selected_query = "";
    	if($selected_notes!='') {
    		$note_selected_query = " and notes_title like ('%".$selected_notes."%') ";
    	}
    	$notes_list_query = "select * from employee_notes where company_id='".$company_id."' and employee_id='".$get['employee_id']."' and is_active='0'".$note_selected_query ." LIMIT ".$offset_limit.",".$no_of_records_per_page;
    	$notes_list = $callConfig->getAllRows($notes_list_query);
    	
    	$note_details['total_notes'] = count($notes_list);
    	foreach ($notes_list as $value) {
    		
    			$shared_id_data = "SELECT id,display_name,user_photo From application_users WHERE id IN (select share_id from application_share where company_id='".$company_id."' and transaction_id='".$value->id."' and is_active='0' and application_table='employee_notes')";
			//echo $shared_id_data;
    			$ssdata = $callConfig->getAllRows($shared_id_data);
			$share_with_details = array();
    			foreach($ssdata as $data){
    				$share_with_list = array();
    				$share_with_list['share_id'] =$data->id;
	    			$share_with_list['shared_display_name'] = $data->display_name;
	    			$share_with_list['shared_image'] =$data->user_photo;
	    			$share_with_details[] = $share_with_list;
    			}   
			$value->share_with_details = $share_with_details;
			$notes_li[] = $value;			
    		
    	}
	$note_details['notes_list'] = $notes_li;
    	//$note_details['share_with'] = $share_with_details; 
    	$querr = "SELECT * FROM employee_notes WHERE id IN ( SELECT `transaction_id` FROM application_share WHERE share_id=".$get['user_id'].")";
    	$share_ss = $callConfig->getAllRows($querr);
    	foreach($share_ss as $share_s){
    		$share_u[] = $share_s;
    	}
    	$note_details['share_u'] = $share_u; 
    	return $note_details;
    }


