    		/*$employeeurl =  $callConfig->selectQuery('employees','*','is_active=0','','','');
    		$employees = $callConfig->getAllRows($employeeurl);
    		foreach($employees as $employee){
    			$emp[$employee->emp_code] = $employee->id;
