function setuppayroll($post,$get){
	global $callConfig;
	$common_field = array('created_by'=>$_SESSION['user_id'],'is_active'=>'0','created_date'=>date("Y-m-d H:i:s"));
	$address = $post['address'].', '.$post['city'].', '.$post['state'].' ,'.$post['pincode'];

	$companies_setup = array('name'=>$post['company_name'],'gstno'=>$post['gst_number'],'telephone'=>$post['phone_number'],'email'=>$post['admin_email'],'created_by'=>$_SESSION['user_id'],'created_date'=>date("Y-m-d H:i:s"),'is_active'=>'0');
	$res=$callConfig->insertRecord(TBL_COMPANIES,$companies_setup);
	$common_field['company_id']=$res['LASTID'];

	$config_setup = array('name'=>$post['company_name'],'contact_address'=>$address,'pan_number'=>$post['pan_number'],'tax_number'=>$post['tan_number'],'gst_number'=>$post['gst_number'],'cin_number'=>$post['cin_number'],'default_payroll_day'=>$post['default_payroll_day'],'liscense_number'=>$post['license_number'],'phone_number'=>$post['phone_number'],'admin_email'=>$post['admin_email'],'industry'=>$post['industry'],'location'=>$post['location'],'CreatedBy'=>$_SESSION['user_id'],'created_at'=>date("Y-m-d H:i:s"),'company_id'=>$res['LASTID'],'is_active'=>'0');
	$res=$callConfig->insertRecord(TBL_CONFIG,$config_setup);

