function setupvendor($post,$get){
	global $callConfig;
	unset($post['document_id']);
	if($get['rid']==''){
		$res=$callConfig->insertRecord(TBL_VENDOR_REGISTERS,$post);
		$transaction_number = $res['LASTID'];
		$attachlist = json_decode($post['attachments'],1);
		foreach ($attachlist as $dvalue) {
			echo $filename = $dvalue['filename'];
			$doctype = $dvalue['document_id'];
			if($filename!=""){
				$fields = array('company_id'=>$_SESSION['company_id'],'application_tablename'=>TBL_VENDOR_REGISTERS,'transaction_number'=>$transaction_number,'transaction_number'=>$doctype,'filename'=>$filename,'created_by'=>$_SESSION['user_id'],'is_active'=>'0','created_date'=>date("Y-m-d H:i:s"));
				$res=$callConfig->insertRecord(TBL_TRANSACTION_DOCUMENTS,$fields);
			}
		}
	}
	else{
		$res=$callConfig->updateRecord(TBL_VENDOR_REGISTERS,$post,'id',$get['rid']);
		$attachlist = json_decode($post['attachments'],1);
		foreach ($attachlist as $dvalue) {
			$filename = $dvalue['filename'];
			$doctype = $dvalue['document_id'];
