/* Announcements Feeds Page Start */
function getannouncements($get){
	global $callConfig;
	$whrconfig ="is_active='0' and company_id=".$get['company_id'];  
	$queryconfig=$callConfig->selectQuery('config','name,display_logo,location',$whrconfig,'','','');
	$config = $callConfig->getAllRows($queryconfig);
	$details['config'] = $config[0];

	$whrannounce_category ="is_active='0' and company_id=".$get['company_id'];  
	$queryannounce_category=$callConfig->selectQuery('announcement_categories','id,announcement_category_name',$whrannounce_category,'','','');
	$announce_category = $callConfig->getAllRows($queryannounce_category);
	$details['announce_category'] = $announce_category;	
	foreach ($details['announce_category'] as $value) {
		$announce_category_id[$value->id] = (array)$value;
		$valid_announce = "SELECT count(id) as count FROM company_announcements WHERE is_active=0 and company_id=".$get['company_id']." and announcement_category_id=".$value->id." and expiry_date>='".date("Y-m-d")."'" ;
		$valid_announces = $callConfig->getRow($valid_announce);
		$announce_category_id[$value->id]['category_count'] = $valid_announces->count;
	}
	$details['announcement_categories'] = $announce_category_id;
	$queryuserannounce = "SELECT * FROM company_announcements WHERE is_active=0 and created_by='".$get['userid']."' and company_id=".$get['company_id']." order by start_date desc" ;
	$userannouncements = $callConfig->getAllRows($queryuserannounce);
	foreach ($userannouncements as $announceskey => $announcesvalue) {
		$userannounces[$announcesvalue->id] = (array)$announcesvalue;
		$querysumm = "SELECT sum(IF(comments!='', 1,0 ) ) as totalcomments,sum(IF(like_type=1, 1,0 ) ) as totallikes ,sum(IF(like_type=2, 1,0 ) ) as totaldislikes FROM summary_announcements WHERE is_active=0 and company_id=".$get['company_id']." and userid=".$get['userid']." and announcement_id=".$announcesvalue->id ;
		$announcessummaryuser = $callConfig->getRow($querysumm); 
		$userannounces[$announcesvalue->id]['totallikes'] = $announcessummaryuser->totallikes == null ? '0' : $announcessummaryuser->totallikes;
		$userannounces[$announcesvalue->id]['totaldislikes'] = $announcessummaryuser->totaldislikes == null ? '0' : $announcessummaryuser->totaldislikes;
