    function getterminatesettings($get){
    	global $callConfig;
    	$whrconfig ="is_active='0' and company_id=".$get['company_id']." and id=".$get['job_title_id'];  
    	$queryconfig=$callConfig->selectQuery('job_titles','notice_period',$whrconfig,'','','');
    	$config = $callConfig->getRow($queryconfig);
    	$notice_period = $config->notice_period;
    	$details['notice_period'] = $notice_period;

    	$whr3 = "company_id = ".$get['company_id']." AND genc_code='SEPERATION_MODE' AND is_active = 0";    
    	$query3=$callConfig->selectQuery(TBL_GENRAL_CODE_DETAILS,'*',$whr3,'','','');
    	$gc_data = $callConfig->getAllRows($query3);
    	foreach ($gc_data as $gc) {
    		$gcdata[$gc->genc_detail_code] = $gc->genc_detail_name;
    	}
    	$details['separation_mode'] = $gcdata;

    	$whr3 = "company_id = ".$get['company_id']." AND genc_code='TERMINATION_TYPE' AND is_active = 0";    
    	$query3=$callConfig->selectQuery(TBL_GENRAL_CODE_DETAILS,'*',$whr3,'','','');
    	$gc_data1 = $callConfig->getAllRows($query3);
    	foreach ($gc_data1 as $gc) {
    		$gcdata1[$gc->genc_detail_code] = $gc->genc_detail_name;
    	}
    	$details['termination_type'] = $gcdata1;

    	$hrconnect_data = "select * from employee_buddies where employee_id='".$get['employee_id']."' and is_active='0' and company_id='".$get['company_id']."'";
    	$hrconnect_details = $callConfig->getRow($hrconnect_data);
    	$hrconnect_id = $hrconnect_details->hr_buddy;
    	$financial_id = $hrconnect_details->finance_buddy;
    	if($hrconnect_id==0 || $hrconnect_id==""){
    		$hrconnect_data = "select * from locations where company_id='".$get['company_id']."' and is_active='0' and id='".$get['location_id']."'";
    		$hrconnect_details = $callConfig->getAllRows($hrconnect_data);
    		$hrconnect_id = $hrconnect_details[0]->hr_connect;
    		if($hrconnect_id==0 || $hrconnect_id=="" ) {
    			$hrconnect_data = "select * from config where company_id='".$get['company_id']."' and is_active='0'";
    			$hrconnect_details = $callConfig->getAllRows($hrconnect_data);
    			$hrconnect_id = $hrconnect_details[0]->default_hr;
    			$hrconnectdetails['hr_connect_id'] = $hrconnect_id;
    		}else {
    			$hrconnectdetails['hr_connect_id'] = $hrconnect_id;
    		}
    	}else {
    		$hrconnectdetails['hr_connect_id'] = $hrconnect_id;
    	}
    	$details['hr_connect'] = $hrconnectdetails['hr_connect_id'];
    	$details['financial_id'] = $financial_id;
    	$qquwey ="SELECT au.id as user_id,emp.id emp_id,au.display_name  display_name FROM application_users au, employees emp WHERE au.company_id = emp.company_id AND au.id = emp.user_id AND emp.is_active=0 AND au.is_active=0 AND emp.id IN (".$details['hr_connect'].",".$details['financial_id'].")";
    	//echo $qquwey;
    	$hrfindd = $callConfig->getAllRows($qquwey);
    	//print_r($hrfindd);
    	foreach($hrfindd as $hrfind){
    		$hrfi[$hrfind->emp_id] = $hrfind->user_id;
    	}
    	$details['hr_user_id'] = $hrfi[$details['hr_connect']];
    	$details['finance_user_id'] = $hrfi[$details['financial_id']];
    	return $details;
    }
   function savetermination($post,$get){
    	global $callConfig;
    	if($get['rid']==''){
			$sendemployedetails = array('employee_id'=>$post['emp_id'],'company_id'=>$get['company_id']);
			
			$returnresp = $this->getempconnect($sendemployedetails);
			//$res = $returnresp; 
			//$res = $sendemployedetails;

			$post['hr_user_id'] = $returnresp['hr_connect'];
			$post['finance_user_id'] = $returnresp['finance_connect'];
    		        $res=$callConfig->insertRecord(TBL_EMPLOYEE_TERMINATIONS,$post);
    	}else{
    		$res=$callConfig->updateRecord(TBL_EMPLOYEE_TERMINATIONS,$post,'id',$get['rid']);
    	}
    	return $res;
    }
