            	$candi=$callConfig->getAllRows($query);
            	foreach($candi as $cand){
            		$array = array('id'=>$cand->id,'name'=>$cand->candidate_name,'sub_name'=>$cand->candidate_email,'field'=>$job[$cand->job_posting_id],'field2'=>$cand->created_date,'field3'=>$cand->candidate_phone,'link'=>'','status'=>$cand->current_status,'link_id'=>$cand->candidate_id);
            		$canda['all'][] = $array;
            		if($cand->current_status == 199){
