            			$canda['rejected'][] = $array;
            		}
            	}
            	$query = "SELECT * FROM `employees` WHERE `vendor_id` =".$get['user_id'];
            	$employees=$callConfig->getAllRows($query);
            	foreach($employees as $cand){
            		$array = array('id'=>$cand->id,'name'=>$cand->display_name,'sub_name'=>$cand->email_id,'field'=>$job[$cand->job_title_id],'field2'=>$cand->created_date,'field3'=>$cand->phone,'status'=>$cand->current_status,'link'=>'','link_id'=>$cand->id);
            		$emp['all'][] = $array;
            		$emp_data[$cand->id] = (array)$cand;
            	}
            	$query = "SELECT * FROM `emp_contracts` WHERE `vendor_id` =".$get['user_id'];
            	$contacts = $callConfig->getAllRows($query);
  	///print_r($contacts); exit;
            	foreach($contacts as $cand){
            		$array = array('id'=>$cand->id,'name'=>$emp_data[$cand->emp_id]['display_name'],'sub_name'=>$emp_data[$cand->emp_id]['email_id'],'field'=>$job[$cand->job_title],'field2'=>$cand->duration_to,'field3'=>$emp_data[$cand->emp_id]['phone'],'status'=>$cand->current_status,'link'=>'','link_id'=>$cand->id);
  		//$array = array('id'=>$cand->id,'name'=>$emp_data[$cand->emp_id]['display_name'],'sub_name'=>'','field'=>$job[$cand->job_title],'field2'=>'','field3'=>'','link'=>'','link_id'=>$cand->id);

            		$tra['all'][] = $array;
            	}
            	$data['0'] = $canda;
            	$data['1'] = $emp;
            	$data['2'] = $emp;
            	$data['3'] = $tra;
            	$data['4'] = array('all_candidates'=>count($canda['all']),'selected'=>count($canda['selected']),'rejected'=>count($canda['rejected']));
  	//echo "<pre>"; print_r($data);
            	return $data;
            }
