            		if($post['puser_id'][$key]!=""){
            			$res=$callConfig->updateRecord('project_users',$inserts_array,'id',$post['puser_id'][$key]);
            		}else{
            			$inres=$callConfig->insertRecord('project_users',$inserts_array);	
            		}

            	}
            	foreach($post['task_name'] as $key=>$task_name){
            		$inserts_task=array('company_id'=>$post['company_id'],'project_id'=>$project_id,'task_name'=>$task_name,'description'=>$post['task_description'][$key],'rate_hours'=>$post['task_rate_hour'][$key],'budget_hours'=>$post['task_budget_hour'][$key],'bill_type'=>$post['bill_type'][$key]=='on'?'1':'0','is_active'=>'0','current_status'=>0,'created_date'=>$post['created_date'],'created_by'=>$post['created_by']);
            		if($post['ptask_id'][$key]!=""){
            			$res=$callConfig->updateRecord('project_tasks',$inserts_task,'id',$post['ptask_id'][$key]);
            		}else{
            			$inres=$callConfig->insertRecord('project_tasks',$inserts_task);	
            		}

   				//echo "<pre>"; print_r($inserts_task); 
            	}
            	return $inres;
            }
