            function getvendorwisereport($get) {
            	global $callConfig;
            	$year = $get['year'];
            	$monthNo = $get['month'];
            	$prev_year = $year-1;
            	$appendcondtion = '';
            	$filterdata = urldecode($get['filterby']);
            	$filters = json_decode($filterdata,1);
            	$curentyear_totalheadcount = 0;
            	$prevyear_totalheadcount = 0;
            	if($filters!=''){
            		$appendcondtion = " and ";
            		foreach ($filters as $filterkey => $filtervalue) {
            			$appendcondtion .= "td.".$filterkey ." IN ( ";
            			$appendcondtion .=  implode(',', array_keys($filtervalue));
            			$appendcondtion .=  " ) and ";
            		}
            		$appendcondtion = substr($appendcondtion, 0, -4);
            	}
            	for($i=1; $i<=12; $i++){
            		$fdate= $prev_year."-".sprintf('%02s', $i)."-01";
            		$ldate= $prev_year."-".sprintf('%02s', $i)."-31";
            		$query="SELECT count(id) as headcount from (SELECT id,joining_date,display_name,designation_id,department_id,employment_category_id,location_id,company_id, if(date_of_leaving!='0000-00-00',date_of_leaving,'".$ldate."') as date_of_leaving  FROM `employees`) as td where td.joining_date <= '".$ldate."' and td.date_of_leaving >='".$fdate."'".$appendcondtion." and td.company_id='".$get['company_id']."'";
            		$empdatas = $callConfig->getRow($query);
            		$prevyear_monthwise_headcount[$i]= $empdatas->headcount;
            		$prevyear_totalheadcount =$empdatas->headcount;  
            	}
            	for($i=1; $i<=12; $i++){
            		if($i>$monthNo){
            			$curyear_monthwise_headcount[$i] = 0;
            		}else{
            			$fdate= $year."-".sprintf('%02s', $i)."-01";
            			$ldate= $year."-".sprintf('%02s', $i)."-31";
            			$query="SELECT count(id) as headcount from (SELECT id,joining_date,display_name,designation_id,department_id,employment_category_id,location_id,company_id, if(date_of_leaving!='0000-00-00',date_of_leaving,'".$ldate."') as date_of_leaving  FROM `employees`) as td where td.joining_date <= '".$ldate."' and td.date_of_leaving >='".$fdate."'".$appendcondtion." and td.company_id='".$get['company_id']."'";
            			$empdatas = $callConfig->getRow($query);
            			$curyear_monthwise_headcount[$i] = $empdatas->headcount;
            			$curentyear_totalheadcount = $empdatas->headcount;  
            		}
            	}
            	$fdate= $year."-".sprintf('%02s', $monthNo)."-01";
            	$ldate= $year."-".sprintf('%02s', $monthNo)."-31";
            	$query_emp="SELECT td.id,td.display_name,td.designation_id,td.department_id,td.joining_date,td.employment_category_id,td.location_id  FROM (SELECT id,joining_date,display_name,designation_id,department_id,employment_category_id,location_id,company_id, if(date_of_leaving!='0000-00-00',date_of_leaving,'".$ldate."') as date_of_leaving  FROM `employees`) as td where td.joining_date <= '".$ldate."' and td.date_of_leaving >='".$fdate."'".$appendcondtion." and td.company_id='".$get['company_id']."'";
            	$emp_id_query = $callConfig->getAllRows($query_emp);
            	foreach ($emp_id_query as $eidvalue) {
            		$selected_employees[$eidvalue->id] = $eidvalue;
            	}
    	//print_r($prevyear_monthwise_headcount);print_r($curyear_monthwise_headcount); exit;
            	$details['years'] = array($year, $prev_year);
            	$details['curyear_monthwise_headcount'] = $curyear_monthwise_headcount;
            	$details['prevyear_monthwise_headcount'] = $prevyear_monthwise_headcount;
            	$details['Total_Head_Count'] = $curentyear_totalheadcount;
            	$details['Total_Head_Count_CurrentYear'] = $curentyear_totalheadcount-$prevyear_totalheadcount;
            	$details['Total_Head_Count_PrevYear'] = $prevyear_totalheadcount;
            	$details['selected_employees'] = $selected_employees;
            	$total_empcategorywise_headcount =0;
            	$total_applicantcategorywise_headcount =0;

            	$total_locationwise_headcount =0;
            	$total_departmentwise_headcount =0;
            	$total_divisionwise_headcount = 0;
            	$query_1="SELECT *  FROM `vendors` WHERE company_id='".$get['company_id']."' and is_active =0";
            	$empdatas1 = $callConfig->getAllRows($query_1);
            	foreach ($empdatas1 as $value1) {
            		$query1="SELECT count(id) as headcount from (SELECT id,joining_date,display_name,designation_id,department_id,vendor_id,location_id,company_id, if(date_of_leaving!='0000-00-00',date_of_leaving,'".$ldate."') as date_of_leaving  FROM `employees`) as td where td.joining_date <= '".$ldate."' and td.date_of_leaving >='".$fdate."' and td.vendor_id=".$value1->id." and td.company_id='".$get['company_id']."'";
            		$empresult = $callConfig->getRow($query1);
            		$empcategorywise_headcount[$value1->display_name] = $empresult->headcount;
            		$employment_category[$value1->id] = $value1->display_name;
            		$vendors[$value1->id] = $value1->display_name;

            		$total_empcategorywise_headcount += $empresult->headcount;
            	}
            	if($total_empcategorywise_headcount!=$curentyear_totalheadcount){
            		$empcategorywise_headcount['undefined'] = $curentyear_totalheadcount-$total_empcategorywise_headcount;
            	}
            	$details['empcategorywise_headcount'] = $empcategorywise_headcount;
            	$details['vendors'] = $vendors;
       //	echo "<pre>"; print_r($details['vendors']); exit;

            	$current_date = date('Y-m-d');
            	$upto1month = date('Y-m-d', strtotime($current_date. ' + 30 days'));

            	$query_1="SELECT * FROM `emp_contracts` WHERE company_id='".$get['company_id']."' and is_active =0 and duration_to between '".$current_date."' and '".$upto1month."'";
            	$empdatas1 = $callConfig->getAllRows($query_1);
            	$wage_emp = 0;
            	foreach ($empdatas1 as $value1) {
            		$query1="SELECT no_hours_day from emp_working_schedules where id=".$value1->working_schedule;
            		$empresult = $callConfig->getRow($query1);
            		$wage_emp += $empresult->no_hours_day * $value1->wage ;
            	}
            	$contract_count[0]= count($empdatas1);
            	$contract_wage[0]= $wage_emp;

            	$upto2month = date('Y-m-d', strtotime($current_date. ' + 61 days'));
            	$query_1="SELECT * FROM `emp_contracts` WHERE company_id='".$get['company_id']."' and is_active =0 and duration_to between '".$upto1month."' and '".$upto2month."'";
            	$empdatas1 = $callConfig->getAllRows($query_1);
            	$wage_emp = 0;
            	foreach ($empdatas1 as $value1) {
            		$query1="SELECT no_hours_day from emp_working_schedules where id=".$value1->working_schedule;
            		$empresult = $callConfig->getRow($query1);
            		$wage_emp += $empresult->no_hours_day * $value1->wage ;
            	}
            	$contract_count[1]= count($empdatas1);
            	$contract_wage[1]= $wage_emp;


            	$upto3month = date('Y-m-d', strtotime($current_date. ' + 120 days'));
            	$query_1="SELECT * FROM `emp_contracts` WHERE company_id='".$get['company_id']."' and is_active =0 and duration_to between '".$upto2month."' and '".$upto3month."'";
            	$empdatas1 = $callConfig->getAllRows($query_1);
            	$wage_emp = 0;
            	foreach ($empdatas1 as $value1) {
            		$query1="SELECT no_hours_day from emp_working_schedules where id=".$value1->working_schedule;
            		$empresult = $callConfig->getRow($query1);
            		$wage_emp += $empresult->no_hours_day * $value1->wage ;
            	}
            	$contract_count[2]= count($empdatas1);
            	$contract_wage[2]= $wage_emp;

            	$upto6month = date('Y-m-d', strtotime($current_date. ' + 180 days'));
            	$query_1="SELECT * FROM `emp_contracts` WHERE company_id='".$get['company_id']."' and is_active =0 and duration_to between '".$upto3month."' and '".$upto6month."'";
            	$empdatas1 = $callConfig->getAllRows($query_1);
            	$wage_emp = 0;
            	foreach ($empdatas1 as $value1) {
            		$query1="SELECT no_hours_day from emp_working_schedules where id=".$value1->working_schedule;
            		$empresult = $callConfig->getRow($query1);
            		$wage_emp += $empresult->no_hours_day * $value1->wage ;
            	}
            	$contract_count[3]= count($empdatas1);
            	$contract_wage[3]= $wage_emp;

            	$upto12month = date('Y-m-d', strtotime($current_date. ' + 360 days'));
            	$query_1="SELECT * FROM `emp_contracts` WHERE company_id='".$get['company_id']."' and is_active =0 and duration_to between '".$upto6month."' and '".$upto12month."'";
