    function createassessments($post,$get){
    	global $callConfig;
    	$rowid=$get['rowid'];
    	$table_setup = $get['table_setup'];
    	$table_questions = $get['table_questions'];
    	$table_options = $get['table_options'];
    	$main = $post['main'];
    	$quesion_data = $post['qustion'];

    	$whr="company_id=".$get['company_id']." and is_active='0' and id=".$main['assessment_assigned_to'];
    	$query=$callConfig->selectQuery(TBL_FILTER_TABLES,'*',$whr,'','','');
    	$shared_content_details = $callConfig->getRow($query);
    	$shared_list = $shared_content_details->content;
    	$shared_list = rtrim($shared_list,'"');
    	$shared_list = ltrim($shared_list,'"');
    	$shared_ids = json_decode($shared_list,1);
    	$assigned_to_employees = json_encode($shared_ids['matches_names'],1);
    	$shared_list1 = rtrim($assigned_to_employees,'"');
    	$shared_list1 = ltrim($shared_list1,'"');
    	$shared_ids1 = json_decode($shared_list1,1);
    	foreach($shared_ids1 as $ids){
    		$shared_idslist[]= $ids['id_value'];
    	}
    	$main['assigned_to_employees'] = json_encode($shared_idslist,1);
    	$main['assigned_to_count']  = count($shared_idslist);
	    //print_r($shared_ids1);exit;
    	if($rowid=="") {
    		$array = array('company_id'=>$main['company_id'],'is_active'=>'0','created_by'=>$main['created_by'],'created_date'=>$main['created_date']);
    		$res=$callConfig->insertRecord($table_setup,$main);
    		$s_id = $res['LASTID'];
    		foreach($shared_ids1 as $ids){
    			$response_array = array('company_id'=>$main['company_id'],'is_active'=>'0','created_by'=>$main['created_by'],'created_date'=>$main['created_date'],'employee_id'=>$ids['id_value'],'assessment_id'=>$s_id,'category'=>$main['category']);
    			$res=$callConfig->insertRecord(TBL_ASSESSMENT_RESPONSES,$response_array);
    		}
    		foreach ($quesion_data as $key => $value) {
    			$value['assessment_id'] = $s_id;
    			$assessment_question_option['assessment_question_option'] = $value['assessment_question_option'];
    			$assessment_question_option['assessment_correct_option'] = $value['assessment_correct_option'];
    			$assessment_question_option['assessment_marks'] = $value['assessment_marks'];

    			$assessment_question_option['assessment_id'] = $s_id;
    			unset($value['assessment_question_option']);
    			unset($value['assessment_correct_option']);
    			unset($value['assessment_marks']);
    			$quesion_array = array_merge($value,$array);
			//print_r($quesion_array); exit;
    			$qres=$callConfig->insertRecord($table_questions,$quesion_array);
    			$assessment_question_option['question_id'] = $qres['LASTID'];
    			$answer_array = array_merge($assessment_question_option,$array);
    			$qrespons=$callConfig->insertRecord($table_options,$answer_array);
			//exit;
    		}
    		$retunn_assessment_id = $s_id;
    	} else {

    		$array = array('company_id'=>$main['company_id'],'is_active'=>'0','updated_by'=>$main['updated_by'],'updated_date'=>$main['updated_date']);
		//print_r($main); echo $table_setup.$rowid; exit;
    		$res=$callConfig->updateRecord($table_setup,$main,'id',$rowid);
		// two update querys - qustiontable and option table is_aactive=1
    		$setisactive = array('is_active'=>'1');
    		$qrespons=$callConfig->updateRecord($table_questions,$setisactive,'assessment_id',$rowid);
    		$qrespons=$callConfig->updateRecord($table_options,$setisactive,'assessment_id',$rowid);
    		$qrespons=$callConfig->updateRecord(TBL_ASSESSMENT_RESPONSES,$setisactive,'assessment_id',$rowid);
    		foreach($shared_ids1 as $ids){
    			$response_array = array('company_id'=>$main['company_id'],'is_active'=>'0','created_by'=>$main['created_by'],'created_date'=>$main['created_date'],'employee_id'=>$ids['id_value'],'assessment_id'=>$rowid,'category'=>$main['category']);
    			$res=$callConfig->insertRecord(TBL_ASSESSMENT_RESPONSES,$response_array);
    		}
    		foreach ($quesion_data as $key => $value) {
			//if(qustionid!='') thn update is_active=0 and values questintabe
			//update is_active=0 and valus in option table conditoon assessment id and question id
			//else = insert to table is_active=0
    			$value['assessment_id'] = $rowid;
    			$assessment_question_option['assessment_question_option'] = $value['assessment_question_option'];
    			$assessment_question_option['assessment_correct_option'] = $value['assessment_correct_option'];
    			$assessment_question_option['assessment_marks'] = $value['assessment_marks'];

    			$assessment_question_option['assessment_id'] = $rowid;
				$question_id = $value['question_id'];//exit;
				unset($value['assessment_question_option']);
				unset($value['assessment_correct_option']);
				unset($value['assessment_marks']);
				unset($value['question_id']);
				unset($value['rid']);
				$quesion_array = array_merge($value,$array);
				if($question_id!=''){
					$qres=$callConfig->updateRecord($table_questions,$quesion_array,'id',$question_id);
					$answer_array = array_merge($assessment_question_option,$array);
					$qrespons=$callConfig->updateRecord($table_options,$answer_array,'question_id',$question_id);
				}else{
					$qres=$callConfig->insertRecord($table_questions,$quesion_array);
					$assessment_question_option['question_id'] = $qres['LASTID'];
					$answer_array = array_merge($assessment_question_option,$array);
					$qrespons=$callConfig->insertRecord($table_options,$answer_array);
				}
			}
			$retunn_assessment_id = $rowid;
		}
		return $retunn_assessment_id;
	}

	function saveassessmentreponses($post, $get) {
		global $callConfig;
	    // set is_active 1 bsed on survey id and empid
		$updatearray = array('is_active'=>'1');
