	function getassessmentsummary($get){
		global $callConfig;

		$tag1 = $get['category'] ==1 ?'Assessments' : '';
		$tag2= $get['category'] ==1 ?'AssginedTo' : '';
		$queryresponse = "SELECT count(id) as total_assessments, sum(assigned_to_count) as collectors  FROM ".TBL_ASSESSMENT_SETUP." WHERE is_active=0 and company_id=".$get['company_id']." and category=".$get['category'] ; 
		$sresponse = $callConfig->getRow($queryresponse);
		$details['summary'][] = array('data'=>$sresponse->total_assessments,'name'=>$tag1,'bgcolor'=>'primary');
		$details['summary'][] = array('data'=>$sresponse->collectors,'name'=>$tag2,'bgcolor'=>'secondary');
		$queryresponse = "SELECT count(id) as total_responses,round(sum(duration_taken)/count(id),2) as avg_duration_taken  FROM ".TBL_ASSESSMENT_RESPONSES." WHERE is_active=0 and company_id=".$get['company_id']." and category=".$get['category']." and current_status=".ST_COMPLETE ; 
		$response = $callConfig->getRow($queryresponse);
		$details['summary'][] = array('data'=>$response->total_responses==''?'0':$response->total_responses,'name'=>'Responses','bgcolor'=>'success');

		$queryresponse = "SELECT count(id) as partial  FROM ".TBL_ASSESSMENT_RESPONSES." WHERE is_active=0 and company_id=".$get['company_id']." and category=".$get['category']." and current_status=".ST_INPROGRESS; 
		$presponse = $callConfig->getRow($queryresponse);

		$details['summary'][] = array('data'=>$presponse->partial==''?'0':$presponse->partial,'name'=>'Partial','bgcolor'=>'warning');
	    //$details['summary'][] = array('data'=>($sresponse->total_assessments-$response->total_responses)==''?'0':($sresponse->collectors-$response->total_responses),'name'=>'Incomplete','bgcolor'=>'info');

		$details['summary'][] = array('data'=>$response->avg_duration_taken==''?'0':$response->avg_duration_taken,'name'=>'Avg Time','bgcolor'=>'dark');
		if($sresponse->total_assessments>0){
			$rate = round(($response->total_responses/$sresponse->total_assessments*100),2);
		}else{
			$rate = "0";
		}
		$details['rate']= $rate." %";

		$whr="company_id=".$get['company_id']." and is_active='0' and category=".$get['category'] ;;
		$query=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP,'*',$whr,'','','');
		$response = $callConfig->getAllRows($query);
		foreach($response as $svalues){
			$assessmentvalues = array('assessment_id'=>$svalues->id,'assessment_name'=>$svalues->assessment_name,'assessment_start_date'=>date('d M, Y',strtotime($svalues->assessment_start_date)),'assessment_end_date'=>date('d M, Y',strtotime($svalues->assessment_end_date)));
			$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$svalues->id;
			$questions=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP_QUESTIONS,'count(id) as totalquestion',$whr,'','','');
			$qresponse = $callConfig->getRow($questions);
			$assessmentvalues['totalquestion'] = $qresponse->totalquestion;
			$assessmented = $svalues->assigned_to_count;
			$whr="company_id=".$get['company_id']." and is_active='0' and assessment_id=".$svalues->id." and category=".$get['category']." and current_status=".ST_COMPLETE  ;
			$questions=$callConfig->selectQuery(TBL_ASSESSMENT_RESPONSES,'count(id) as totalresponse',$whr,'','','');
			$qresponse = $callConfig->getRow($questions);

			if($qresponse->totalresponse>0){
				$completionrate = round(($qresponse->totalresponse/$assessmented*100),2);
			}else{
				$completionrate = "0";
			}

			$assessmentvalues['totalresponse'] = $qresponse->totalresponse == '' ? '0' : $qresponse->totalresponse;
			$assessmentvalues['completionrate'] = $completionrate == '' ? "0 %" : $completionrate." %";

			if($completionrate==100){
				$assessmentvalues['completionratecolor'] = "success";
			}else if($completionrate>=80){
				$assessmentvalues['completionratecolor'] = "primary";
			}
			else if($completionrate>=60 && $completionrate <80){
				$assessmentvalues['completionratecolor'] = "warning";
			}
			else if($completionrate>=50 && $qresponse->completionrate <60){
				$assessmentvalues['completionratecolor'] = "info";
			}
			else {
				$assessmentvalues['completionratecolor'] = "danger";
			}
			$details['assessment_details'][] = $assessmentvalues;
		}
		$assessmenttypes= $get['category'] ==1 ?'ASSESSMENT_TYPES' : '';
		$whr2="company_id=".$get['company_id']." and is_active='0' and genc_code='".$assessmenttypes."'";
		$query=$callConfig->selectQuery('general_code_details','genc_detail_code,genc_detail_name',$whr2,'','','');
		$details['qustion_types'] = $callConfig->getAllRows($query);
		foreach($details['qustion_types'] as $qustion_types){
			$qtype[$qustion_types->genc_detail_code] = $qustion_types->genc_detail_name;

			$whr="company_id=".$get['company_id']." and is_active='0' and assessment_type='".$qustion_types->genc_detail_code."'";
			$questions=$callConfig->selectQuery(TBL_ASSESSMENT_SETUP,'count(id) as totaltypequestion',$whr,'','','');
			$qresponse = $callConfig->getRow($questions);
			$assessment_qtypes[$qustion_types->genc_detail_name] = $qresponse->totaltypequestion;


		}
		$details['assessment_qtypes'] = $assessment_qtypes;
		return $details;
	}

