 function employeedashboard($get){
	 	global $callConfig;
	 	$edate = date('Y')."-01-01";
	 	$endate = date('Y')."-12-31";
	 	$yy = date('Y');
//new
	 	$today_date = date("Y-m-d");
	 	$day = date("l");
	 	$query="SELECT id,display_name  FROM `employees` WHERE company_id = '".$get['company_id']."' and is_active =0";
	 	$empdatas = $callConfig->getAllRows($query);
	 	foreach ($empdatas as $value) {
	 		$empidlist[$value->id] = $value->display_name;
	 	}
//working days (monday,tursday,saturday)...
	 	$attstc = "SELECT * FROM attendance_settings WHERE is_active=0 and company_id=".$get['company_id'];
	 	$atsdata = $callConfig->getRow($attstc);
	 	$workingdays = $atsdata->working_days;
	 	$working_days = json_decode($workingdays,1);
//attendance key (wornking, )
	 	$shiftkeys = "SELECT * FROM attendance_key_types WHERE is_active=0 and company_id=".$get['company_id'];
	 	$shiftkeysdata = $callConfig->getAllRows($shiftkeys);
	 	foreach ($shiftkeysdata as $skey=>$svalue) {
	 		$shift[$svalue->key_short_code] = (array)$svalue;
	 	}
	 	$holidays = "SELECT holiday_date FROM holidays WHERE is_active=0 and company_id=".$get['company_id'];
	 	$holidaysdata = $callConfig->getAllRows($holidays);
	 	foreach ($holidaysdata as $hkey=>$hvalue) {
	 		$holidaysdatas[] = $hvalue->holiday_date;
	 	}
	 	$leaves = "SELECT employee_id FROM `employee_leaves` WHERE leave_from <= '".$today_date."' AND leave_to >= '".$today_date."' and company_id=".$get['company_id']." and is_active=0 and current_status = '".ST_APPROVED."'";

	 	$leavesdata = $callConfig->getAllRows($leaves);
	 	foreach ($leavesdata as $hkey=>$leave) {
	 		$employeeleaves[] = $leave->employee_id;
	 	}
//attaindance date
	 	$present_cnt = 0;
	 	$absent_cnt = 0;
	 	$plannedLeave_cnt = 0;
	 	foreach($empidlist as $key=>$emplists){
	 		$attendancequery = "SELECT id from  employee_daily_attendances where is_active=0 AND employee_id = ".$key." AND  `attendace_date` = '".$today_date."' ";
	 		$attendata = $callConfig->getRow($attendancequery);
	if(isset($attendata->id)){										// present attaindants
		$present_cnt++;
	}else{
		if(in_array($day,$working_days)){    						// working day yes
				if(in_array($today_date,$holidaysdatas)){			//holiday Yes
					$msg_day ="Today Holiday"; 
				}else{												//holiday No
					if(in_array($key,$employeeleaves)){				//Leave Yes
						$plannedLeave_cnt++;  
					}else{											//Leave No
						$absent_cnt++;
						
					}
				}
		}else{                                        				// working day No
			$msg_day =  "Not Working Day";
		}	
	}
}
$query="SELECT SUM(if(`employee_type`=1,1,0))as regular, SUM(if(`employee_type`=2,1,0))as contact, SUM(if(`gender`='M',1,0))as male, SUM(if(`gender`='F',1,0))as female, count(DISTINCT(reporting_manager_id)) as manger_count, COUNT(id) as em_count FROM `employees` WHERE company_id = '".$get['company_id']."' and is_active=0";

		//echo $query; exit;
$nempdata = $callConfig->getRow($query);	
$data['nemp'] = $nempdata;
$pre_year = date("Y",strtotime("-1 year")); 
$pre_start_date = $pre_year."-01-01";
$pre_endate = $pre_year."-12-31";
$pri_query="SELECT COUNT(id) as em_count FROM `employees` WHERE  company_id = '".$get['company_id']."' and is_active=0  AND `joining_date` <= '".$pre_endate."'";
$pre_nempdata = $callConfig->getRow($pri_query);	
$data['privew_year_total_emp_count'] = $pre_nempdata->em_count;
$mequery= "SELECT count(id) as joinn FROM `employees` WHERE company_id = '".$get['company_id']."' and `joining_date` < '".$endate."' AND is_active=0";
$medata = $callConfig->getRow($mequery);	
$data['joining'] = $medata->joinn;

$etquery	= "SELECT count(id) as relive FROM `employee_terminations` WHERE  `releive_date` <= '".$endate."' AND is_active=0";
$etdata = $callConfig->getRow($etquery);	
$data['relive'] = $etdata->relive;

$data['averge_employee'] = '211';
$ssdate =  date("Y-m-d");
$resultDays = array('Monday' => 0,'Tuesday' => 0,'Wednesday' => 0,'Thursday' => 0,'Friday' => 0,'Saturday' => 0,'Sunday' => 0);
$startDate = new DateTime($edate);
$endDate = new DateTime(date('Y-m-d'));
while($startDate <= $endDate ){
	$timestamp = strtotime($startDate->format('d-m-Y'));
	$weekDay = date('l', $timestamp);
	$resultDays[$weekDay] = $resultDays[$weekDay] + 1;
	$startDate->modify('+1 day');
}
$days = $resultDays['Monday']+$resultDays['Tuesday']+$resultDays['Wednesday']+$resultDays['Thursday']+$resultDays['Friday'];
$letquery	= "SELECT sum(leave_days) as leaves FROM `employee_leaves` WHERE  company_id = '".$get['company_id']."' and `leave_from` >='".$edate."' AND `leave_from` <= '".$endate."' AND is_active=0";
$letdata = $callConfig->getRow($letquery);	
$data['absent'] = $letdata->leaves;
$data['averge_employee'] = '77';
$data['averge_absent'] = number_format(100-($letdata->leaves/$days)*100,2);
$ssdate = date("Y-m-d", strtotime($ssdate."-11 month"));
for($i=1;$i<13;$i++){
	$new_date_end_month  = date('Y-m-t',strtotime($ssdate));
	$squery = "SELECT count(id) as acemp FROM `employees` WHERE company_id = '".$get['company_id']."' AND is_active=0 and `joining_date` < '".$new_date_end_month."'";
			//echo $squery."<br>";
	$acdd = $callConfig->getRow($squery);	
			//print_r($acdd);
	$actemp = $acdd->acemp;
	$rquery ="SELECT COUNT(id) as empter FROM `employee_terminations` WHERE  company_id = '".$get['company_id']."' AND is_active=0 and `releive_date` < '".$new_date_end_month."'";
	$rdd = $callConfig->getRow($rquery);	
				//echo $rquery."<br>";print_r($rdd);
	$recount = $rdd->empter;
	$fd['val'] = $actemp-$recount;
	 	//	$fd['val'] = $actemp;
	 		//$fd['name'] = date('Y-m-t',strtotime($yy.'-'.$i));
	$fd['name'] = $new_date_end_month;
	
	$fd['val2'] = $recount;
	$fdd[]=$fd;

	$yearss = date("Y", strtotime($ssdate));
	$monthss = date("m", strtotime($ssdate));

	$pquery = "SELECT pay_month, SUM(gross_pay) as gpay FROM `payroll` WHERE  company_id = '".$get['company_id']."' and `pay_year`= '".$yearss."' AND `pay_month`= '".$monthss."' GROUP BY pay_month";
	$pdata = $callConfig->getRow($pquery);
	$pr[date("Y-m-t", strtotime($ssdate))]	 = $pdata->gpay!=""?$pdata->gpay:0;
	$ssdate = date("Y-m-d", strtotime($ssdate."+1 month"));	
}
$data['payroll'] = $pr;
$data['fgraph'] = $fdd;
$data['todayattendants'] = array("present"=>$present_cnt,"absent"=>$absent_cnt,"planned_leave"=>$plannedLeave_cnt,"total_emp"=>count($empidlist),'Todayday'=>$msg_day);
return $data;
}


	 function togetVendorAgreementexpirelist($get){
	 	global $callConfig;
	 	$query= "SELECT ven.`company_id`, ven.`id`, ven.image, ven.display_name, venag.`agreement_name`, venag.`agreement_ref_no`, venag.`signed_date`, venag.`expiry_date`, venag.`file_url`, DATEDIFF(venag.`expiry_date`, NOW()) as diff_days FROM vendors ven, vendor_agreements venag WHERE ven.id = venag.vendor_id AND ven.company_id = venag.company_id AND ven.company_id = 1 AND ven.is_active = '0' AND venag.`expiry_date` < (NOW() + INTERVAL 120 day)";
	 	$exdata = $callConfig->getAllRows($query);
	 	foreach($exdata as $ex){
	 		if($ex->diff_days>0 && $ex->diff_days<8){
	 			$return['week'][] = $ex;
	 		}
	 		if( $ex->diff_days>0 && $ex->diff_days<31){
	 			$return['month'][] = $ex;
	 		}
	 		if($ex->diff_days>0 && $ex->diff_days<120){
	 			$return['qtr'][] = $ex;
	 		}
	 	}
	 	return $return;
	 }
	 function getemprequests($get) {
	 	global $callConfig;
	 	$sql = "select * from food_options where company_id='".$get['company_id']."' and is_active='0'";
	 	$foodoptions = $callConfig->getAllRows($sql);
	 	$sql = "select * from locations where company_id='".$get['company_id']."' and is_active='0'";
	 	$location = $callConfig->getAllRows($sql);

	 	$datecondition = "AND (efo.stop_date is null or (current_date() between efo.start_date and efo.stop_date))";
	 	if($get['fromdate']!='' || $get['todate']){
	 		$datecondition =  "AND (efo.stop_date<='".$get['todate']."') and efo.start_date >='".$get['fromdate']."'";
	 	}
	 	$queryresponse = "SELECT efo.location_id as location_id,
	 	efo.emp_id,
	 	emp.display_name,
	 	efo.food_options option_value,
	 	fo.food_option option_name
	 	FROM     employees emp, employee_food_requests efo, food_options fo
	 	WHERE     emp.id = efo.emp_id
	 	AND        emp.company_id = efo.company_id
	 	AND        emp.is_active = 0
	 	AND        efo.is_active = 0
	 	AND        fo.company_id = emp.company_id
	 	AND        fo.id = efo.food_options
	 	AND        fo.is_active = 0
	 	".$datecondition." order by 1, 2"; 
	 	$allresponse = $callConfig->getAllRows($queryresponse);

	 	foreach($allresponse as $data){
	 		foreach($foodoptions as $foodtype){
	 			$foodoptiondata[$foodtype->id] = $foodtype->food_option;
	 			if($foodtype->id==$data->option_value){
	 				$food_option_array[$foodtype->id][] = $data;
	 				foreach($location as $loc){
	 					if($loc->id==$data->location_id){
	 						$loc_food_option[$foodtype->id][$loc->id][$data->emp_id] = $data;
	 					}
	 				}
	 			}
	 		}

	 	}
	 	$details['summary']=$food_option_array;
	 	$details['foodoptiondata']=$foodoptiondata;
	 	$details['locfooddata']=$loc_food_option;

	 	$transport_datecondition = "AND (current_date() <= efo.created_date)";
	 	if($get['fromdate']!='' || $get['todate']){
	 		$transport_datecondition = "AND (efo.created_date between '".$get['fromdate']."' and '".$get['todate']."')";
	 	}

	 	$queryresponse = "SELECT efo.location_id as location_id,
	 	efo.employee_id,emp.display_name FROM employees emp, employee_transport_requests efo
	 	WHERE     emp.id = efo.employee_id
	 	AND        emp.company_id = efo.company_id
	 	AND        emp.is_active = 0
	 	AND        efo.is_active = 0
	 	".$transport_datecondition." order by 1, 2"; 
	 	$allresponse = $callConfig->getAllRows($queryresponse);
	 	foreach($allresponse as $data){
	 		$total_transport_req[] = $data;
	 		foreach($location as $loc){
	 			if($loc->id==$data->location_id){
	 				$transport_option[$loc->id][$data->employee_id] = $data;
	 			}
	 		}
	 	}

	 	$details['transport']=$transport_option;
	 	$details['transport_req']=count($total_transport_req)==''?'0':count($total_transport_req);
		//echo "<pre>"; print($details['transport_req']);
	 	return $details;
	 }


	 function getempreport($get)
	 {
	 	global $callConfig;
	 	$filterdata = urldecode($get['filterby']);
	 	$filters = json_decode($filterdata,1);
	 	if($filters!=''){
	 		$appendcondtion = " and ";
	 		foreach ($filters as $filterkey => $filtervalue) {
	 			$appendcondtion .= $filterkey ." IN ( ";
	 			$appendcondtion .=  implode(',', array_keys($filtervalue));
	 			$appendcondtion .=  " ) and ";
	 		}
	 		$appendcondtion = substr($appendcondtion, 0, -4);
	 	}

	 	if($get['empidlist']!=''){
	 		$empids = urldecode($get['empidlist']);
	 		$empids = json_decode($get['empidlist'],1);
	 		$emplistfilter = implode(',',$empids);
	 		$appendcondtion .= ' and id in ('.$emplistfilter.')';
	 	}

	 	$query="SELECT * from employees where company_id=".$get['company_id']." and is_active='0'".$appendcondtion;
	 	$empdata = $callConfig->getAllRows($query);
	 	foreach($empdata as $emp){
	 		$empdetails[$emp->id] = $emp;
	 	}
	 	$details['emp_data']= $empdetails;
	 	return $details;

	 }
	function bugetvendorrareporttest($get){
	global $callConfig;
	if($get['fromdate']!=""){
		$ym = explode("-", $get['fromdate']);
		$month = $ym[1];
		$year = $ym[0];
	}else{
		$month = date('m');
		$year = date('Y');
	}
$query="SELECT DISTINCT
    vendor_id,
    vendor_name,
    contact_person,
    employee_id,
    employee_name,
    department_id,
    location_id,
    vertical_id,
    cost_center_id,
    job_title,
    emp_billable,
    billable_hrs,
    nonbillable_hrs,
    leave_days_from + leave_days_to AS leave_days,
	experience_base,
    current_status,
    l_item_price budgeted_amount,
    l_billable_amount billable_amount,
    vrc_item_price vrc_budgeted_amount,
    vrc_billable_amount, 
    (
        SUM(nonbillable_hrs) *(
            SUM(l_billable_amount) / SUM(billable_hrs)
        )
    ) AS nonbillable_amount,
    (
        DATEDIFF(NOW(), `first_working_date`) / 365) exp_first_working,
        (
            total_experiance +(
                DATEDIFF(NOW(), `joining_date`) / 365)
            ) exp_joining_date,
            min_exp,
            max_exp,
            mpc_uom,
            vrc_uom,
            joining_date,
            total_experiance,
            CASE WHEN(
                total_experiance +(
                    DATEDIFF(NOW(), `joining_date`) / 365)
                ) BETWEEN min_exp AND max_exp THEN '' ELSE 'Experiance Missmatch'
            END remark
        FROM
            (
            SELECT
                emp.vendor_id AS vendor_id,
                vend.display_name AS vendor_name,
                vend.contact_person,
                emp.id employee_id,
                emp.first_working_date,
                COALESCE(emp.joining_date, CURRENT_DATE) AS joining_date,
                emp.department_id AS department_id,
                emp.location_id AS location_id,
                emp.vertical_id AS vertical_id,
                emp.cost_center_id AS cost_center_id,
                emp.billable AS emp_billable,
                COALESCE(emp.total_experiance, '0') AS total_experiance,
                mpcitems.purchase_uom as mpc_uom,
                vriitems.purchase_uom as vrc_uom, 
				vriitems.experience_base,
                (
                SELECT
                    job_title
                FROM
                    job_titles jt
                WHERE
                    jt.id = emp.job_title_id AND jt.company_id = emp.company_id
            ) job_title,
            emp.display_name employee_name,
            (
            SELECT
                SUM(billable_hrs)
            FROM
                project_timesheets pt
            WHERE
                pt.company_id = emp.company_id AND pt.emp_id = emp.id AND MONTH(pt.timesheet_date) = '".$month."'  AND YEAR(pt.timesheet_date) = '".$year."'
        ) billable_hrs,
        (
        SELECT
            SUM(nonbillable_hrs)
        FROM
            project_timesheets pt
        WHERE
            pt.company_id = emp.company_id AND pt.emp_id = emp.id AND MONTH(pt.timesheet_date) = '".$month."'  AND YEAR(pt.timesheet_date) = '".$year."'
    ) nonbillable_hrs,
    (
    SELECT
        SUM(bill_amount)
    FROM
        project_timesheets pt
    WHERE
        pt.company_id = emp.company_id AND pt.emp_id = emp.id AND MONTH(pt.timesheet_date) = '".$month."'  AND YEAR(pt.timesheet_date) = '".$year."'
) l_billable_amount,
CASE WHEN mpcitems.purchase_uom = 'PT' THEN mpcitems.item_price / 3 WHEN mpcitems.purchase_uom = 'PS' THEN mpcitems.item_price / 6 WHEN mpcitems.purchase_uom = 'PY' THEN mpcitems.item_price / 12 ELSE mpcitems.item_price
        END l_item_price,
          (
    SELECT
        SUM(vrc_billable_amount)
    FROM
        project_timesheets pt
    WHERE
        pt.company_id = emp.company_id AND pt.emp_id = emp.id AND MONTH(pt.timesheet_date) = '".$month."' AND YEAR(pt.timesheet_date) = '".$year."'
) vrc_billable_amount,
CASE WHEN vriitems.purchase_uom = 'PT' THEN vriitems.item_price / 3 WHEN vriitems.purchase_uom = 'PS' THEN vriitems.item_price / 6 WHEN vriitems.purchase_uom = 'PY' THEN vriitems.item_price / 12 ELSE vriitems.item_price
        END vrc_item_price,
        (
        SELECT
            DATEDIFF(
                LEAST(
                    el.leave_to,
                    last_day(el.leave_from)
                ),
                el.leave_from
            )
        FROM
            employee_leaves el
        WHERE
            el.company_id = emp.company_id AND el.employee_id = emp.id AND MONTH(el.leave_from) = '".$month."'  AND YEAR(el.leave_from) = '".$year."'
    ) leave_days_from,
    (
    SELECT
        DATEDIFF(
            el2.leave_to,
            GREATEST(
                el2.leave_from,
                DATE_SUB(
                    LAST_DAY(el2.leave_to),
                    INTERVAL DAY(LAST_DAY(el2.leave_to)) - 1 DAY
                )
            )
        )
    FROM
        employee_leaves el2
    WHERE
        el2.company_id = emp.company_id AND el2.employee_id = emp.id AND MONTH(el2.leave_to) = '".$month."'  AND YEAR(el2.leave_to) = '".$year."'
) leave_days_to,
vriitems.min_exp,
vriitems.max_exp,
(
    SELECT
        sts.name
    FROM
STATUS
    sts
WHERE
    sts.name_value = emp.current_status AND sts.company_id = emp.company_id
) current_status
FROM
    employees emp,
    vendors vend,
    manpower_contracts vrc,
    mpc_items mpcitems,
    emp_work_order ewo,
    vrc_items vriitems,
    eba_vendors_allocations ebava,
    application_users au
WHERE
    emp.company_id = 1 AND emp.is_active = '0' AND vend.company_id = emp.company_id AND vend.id = emp.vendor_id AND vrc.company_id = emp.company_id AND mpcitems.company_id = vrc.company_id AND mpcitems.transaction_id = vrc.id AND vrc.customer_id = emp.vendor_id AND ewo.company_id = emp.company_id AND ewo.emp_id = emp.id AND mpcitems.transaction_id = ewo.work_order_id AND mpcitems.id = ewo.work_order_detail_id AND vriitems.company_id = ewo.company_id AND vriitems.transaction_id = ewo.vrc_id AND vriitems.id = ewo.vrc_item_id AND ebava.company_id = ewo.company_id AND ewo.is_active = ebava.is_active AND vrc.is_active = vriitems.is_active AND ewo.is_active = vrc.is_active AND emp.company_id = au.company_id AND au.id = emp.user_id AND CASE WHEN 3 != '".$get['user_type']."' THEN(
        ('1' = '".$get['admin_type']."') OR(au.reports_to = '".$get['user_id']."') 
         OR( fn_employee_buddy_id(emp.company_id, emp.id, 'HR') ='".$get['user_id']."'
        ) OR(  fn_employee_buddy_id(emp.company_id, emp.id, 'FIN') = '".$get['user_id']."' 
       )

    ) ELSE(
        vend.id =(
        SELECT
            id
        FROM
            vendors ven2
        WHERE
            ven2.email = '".$get['user_email']."'
    )
    )
        END
    ) abc
GROUP BY
    vendor_id,
    vendor_name,
    l_item_price,
    employee_id,
    employee_name,
    job_title,
    current_status,
    min_exp,
    max_exp,
    mpc_uom,
    vrc_uom
    ,vrc_item_price,experience_base";

	$return = $callConfig->getAllRows($query);
	return $return;
}
	
	
	function bugetvendorrareport($get){
	global $callConfig;
	if($get['fromdate']!=""){
		$ym = explode("-", $get['fromdate']);
		$month = $ym[1];
		$year = $ym[0];
	}else{
		$month = date('m');
		$year = date('Y');
	}
	$startdate = date("Y-m-d",strtotime($year."-".$month."-01"));
	$enddate = date("Y-m-t",strtotime($year."-".$month."-01"));
$query="SELECT	emp.vendor_id,
		(
            SELECT	vend.display_name
            FROM	vendors vend
            WHERE	vend.company_id = emp.company_id
            AND		vend.id = emp.vendor_id
        )vendor_name, 
		emp.id as employee_id, 
        emp.display_name as employee_name, 
		emp.department_id,
		emp.location_id,
		emp.vertical_id,
        (
            SELECT	dept.department_name	
            FROM 	departments dept
            WHERE	dept.company_id = emp.company_id
            AND		dept.id = emp.department_id
        )department_name,
		au.cost_center as cost_center_id,
        (
            SELECT	cc.cost_center_name
            FROM 	cost_centers cc
            WHERE	cc.company_id = au.company_id
            AND		cc.id = au.cost_center
        )cost_center_name,
        emp.job_title_id as job_title,
        (
            SELECT	jt.job_title
            FROM 	job_titles jt
            WHERE	jt.company_id = emp.company_id
            AND		jt.id = emp.job_title_id
        ) job_title,
        emp.billable as emp_billable,
		empptsumm.billable_hrs, 
		empptsumm.nonbillable_hrs,
		empleaves.leave_days,
		vrc_vrcitems.experience_base,
		(
			SELECT	sts.name
			FROM	status sts
			WHERE	sts.company_id = emp.company_id
			AND 	sts.name_value = emp.current_status 
		)current_status,
		(
            SELECT		
            	CASE 
                    WHEN mpcitems.purchase_uom = 'PT' 
                        THEN mpcitems.item_price / 3 
                    WHEN mpcitems.purchase_uom = 'PS' 
                        THEN mpcitems.item_price / 6 
                    WHEN mpcitems.purchase_uom = 'PY' 
                        THEN mpcitems.item_price / 12 
                    ELSE mpcitems.item_price
				END
            FROM	manpower_contracts mpc,	mpc_items mpcitems
            WHERE	mpc.company_id = emp.company_id
            AND		mpc.company_id = mpcitems.company_id
            AND		mpc.id = mpcitems.transaction_id
            AND		mpc.id = empwo.work_order_id
			AND		mpcitems.id = empwo.work_order_detail_id
        )budgeted_amount,
		empptsumm.billable_amount,
        (
            SELECT		
            	CASE 
                    WHEN vrcitems.purchase_uom = 'PT' 
                        THEN vrcitems.item_price / 3 
                    WHEN vrcitems.purchase_uom = 'PS' 
                        THEN vrcitems.item_price / 6 
                    WHEN vrcitems.purchase_uom = 'PY' 
                        THEN vrcitems.item_price / 12 
                    ELSE vrcitems.item_price
				END
            FROM	vendor_rate_cards vrc,	vrc_items vrcitems
            WHERE	vrc.company_id = emp.company_id
            AND		vrc.company_id = vrcitems.company_id
            AND		vrc.id = vrcitems.transaction_id
            AND		vrc.id = empwo.vrc_id
			AND		vrcitems.id = empwo.vrc_item_id
         )vrc_budgeted_amount,
		vrc_billable_amount,
		(empptsumm.nonbillable_hrs * empptsumm.rate_per_hrs) as nonbillable_amount,
		-- DATEDIFF(NOW(), emp.first_working_date) / 365) exp_first_working,
        (
            emp.total_experiance +(
                DATEDIFF(NOW(), emp.joining_date) / 365)
        )exp_joining_date,
		vrc_vrcitems.min_exp,
		vrc_vrcitems.max_exp,
		mpc_mpcitems.mpcitm_purchase_uom as mpc_uom,
 		vrc_vrcitems.vrcitm_purchase_uom as vrc_uom,
		emp.joining_date,
		COALESCE(emp.total_experiance, '0') AS total_experiance,
		CASE WHEN(
                total_experiance +(
                    DATEDIFF(NOW(), `joining_date`) / 365)
                ) BETWEEN min_exp AND max_exp THEN '' ELSE 'Experiance Missmatch'
			END remark,
        au.reports_to,    
 		empwo.work_order_id,
		empwo.work_order_detail_id,
		empwo.vrc_id,
		empwo.vrc_item_id,
        mpc_mpcitems.mpc_item_price,	
        vrc_vrcitems.vrc_item_price
FROM	employees emp
		LEFT JOIN (	SELECT	pt.company_id, pt.emp_id, pt.work_order, SUM(billable_hrs) billable_hrs, SUM(bill_amount) billable_amount, SUM(nonbillable_hrs) nonbillable_hrs, SUM(vrc_billable_amount) vrc_billable_amount, pt.rate_per_hrs 
				FROM	project_timesheets pt
				WHERE	pt.timesheet_date >='".$startdate."' AND pt.timesheet_date <='".$enddate."'
              	GROUP BY pt.company_id, pt.emp_id, pt.work_order, pt.rate_per_hrs
			)empptsumm on (	empptsumm.company_id = emp.company_id AND empptsumm.emp_id = emp.id )
		JOIN application_users au on ( emp.company_id = au.company_id and emp.user_id = au.id)
		LEFT JOIN  (	SELECT	el.company_id, el.employee_id, el.leave_from, el.leave_to,
						DATEDIFF(LEAST(el.leave_to,last_day(el.leave_from)),el.leave_from)+ 
						DATEDIFF(el.leave_to,GREATEST(el.leave_from,DATE_SUB(LAST_DAY(el.leave_to),INTERVAL DAY(LAST_DAY(el.leave_to)) - 1 DAY))) leave_days
				FROM	employee_leaves el
				WHERE	((el.leave_from >='".$startdate."' AND el.leave_from <='".$enddate."') OR (el.leave_to>='".$startdate."' AND el.leave_to <='".$enddate."'))
			)empleaves on ( empleaves.company_id = emp.company_id AND empleaves.employee_id = emp.id )
		LEFT JOIN	(
						SELECT	ewo.company_id, ewo.emp_id, ewo.work_order_id, ewo.work_order_detail_id, ewo.vrc_id, ewo.vrc_item_id
						FROM	emp_work_order ewo
					)empwo on ( empwo.company_id = emp.company_id AND empwo.emp_id = emp.id AND empptsumm.work_order = empwo.work_order_id)  
		LEFT JOIN	(
						SELECT mpc.company_id, mpc.id work_order_id, mpcitems.id work_order_detail_id, mpcitems.purchase_uom mpcitm_purchase_uom,		
							CASE 
								WHEN mpcitems.purchase_uom = 'PT' 
									THEN mpcitems.item_price / 3 
								WHEN mpcitems.purchase_uom = 'PS' 
									THEN mpcitems.item_price / 6 
								WHEN mpcitems.purchase_uom = 'PY' 
									THEN mpcitems.item_price / 12 
								ELSE mpcitems.item_price
							END mpc_item_price
						FROM	manpower_contracts mpc,	mpc_items mpcitems
						WHERE	mpc.company_id = mpcitems.company_id
						AND		mpc.id = mpcitems.transaction_id
					)mpc_mpcitems on ( mpc_mpcitems.company_id = emp.company_id AND mpc_mpcitems.work_order_id = empwo.work_order_id AND  mpc_mpcitems.work_order_detail_id = empwo.work_order_detail_id)
		LEFT JOIN	(
						SELECT vrc.company_id, vrc.id vrc_id, vrcitems.id vrc_detail_id, vrcitems.purchase_uom vrcitm_purchase_uom, 
            					vrcitems.experience_base, vrcitems.max_exp, vrcitems.min_exp, 		
							CASE 
								WHEN vrcitems.purchase_uom = 'PT' 
									THEN vrcitems.item_price / 3 
								WHEN vrcitems.purchase_uom = 'PS' 
									THEN vrcitems.item_price / 6 
								WHEN vrcitems.purchase_uom = 'PY' 
									THEN vrcitems.item_price / 12 
								ELSE vrcitems.item_price
							END vrc_item_price
						FROM	vendor_rate_cards vrc,	vrc_items vrcitems
						WHERE	vrc.company_id = vrcitems.company_id
						AND		vrc.id = vrcitems.transaction_id
					)vrc_vrcitems on ( vrc_vrcitems.company_id = emp.company_id AND vrc_vrcitems.vrc_id = empwo.vrc_id AND  vrc_vrcitems.vrc_detail_id = empwo.vrc_item_id)
 WHERE emp.vendor_id IS NOT NULL
 AND 	(
			CASE	WHEN '3' <> '".$get['user_type']."'  
						THEN(
								('1' = '".$get['admin_type']."') OR (au.reports_to = '".$get['user_id']."') 
								OR(fn_employee_buddy_id(emp.company_id, emp.id, 'HR') ='".$get['user_id']."') 	
								OR(fn_employee_buddy_id(emp.company_id, emp.id, 'FIN') = '".$get['user_id']."')
							)
					ELSE(
							emp.vendor_id =
								(
									SELECT
										id
									FROM
										vendors ven2
									WHERE
										ven2.email = '".$get['user_email']."'
								)
						)
				END
		)";
	$return = $callConfig->getAllRows($query);
	return $return;
}
	
