	}
	function getcandidatefeedbackresult($get){

		global $callConfig;
		$whr2="company_id=".$get['company_id']." and is_active='0' and genc_code='SURVEY_QTYPE'";
		$query=$callConfig->selectQuery('general_code_details','genc_detail_code,genc_detail_name',$whr2,'','','');
		$deta['qustion_types'] = $callConfig->getAllRows($query);

		$whr="company_id=".$get['company_id']." and is_active='0' and job_title_id in('1')";
		$query=$callConfig->selectQuery('job_feedback_setup','*',$whr,'','','');
		//echo $query;
		$details = $callConfig->getAllRows($query);
		//print_r($details);
		foreach($details as $detail){
			$detail_id = $detail->id;
			$whr="company_id=".$get['company_id']." and is_active='0' and job_feedback_setup_id=".$detail_id;
			$query=$callConfig->selectQuery('job_feedback_questions','*',$whr,'','','');
		//echo $query;
			$survey_qustion_details = $callConfig->getAllRows($query);
		//print_r($survey_qustion_details);
			$disp_question=array();
			foreach ($survey_qustion_details as $value) {
				$whr="company_id=".$get['company_id']." and is_active='0' and job_feedback_setup_id=".$detail_id." and question_id=".$value->id;
				$query_ans=$callConfig->selectQuery('job_feedback_question_options','*',$whr,'','','');
				$survey_answer_details = $callConfig->getRow($query_ans);
				$disp_question[$value->id]['survey_question'] = $value->feedback_question;
				$disp_question[$value->id]['job_feedback_setup_id'] = $value->job_feedback_setup_id;
				$disp_question[$value->id]['options_display_type'] = $value->options_display_type;
				$disp_question[$value->id]['require_response'] = $value->require_response;
				$disp_question[$value->id]['allow_multiple_selections'] = $value->allow_multiple_selections;
				$disp_question[$value->id]['survey_question_option'] = $survey_answer_details->feedback_question_option;
			}
			$question[$detail_id]= $disp_question;
		}

		$query ="SELECT * FROM `job_feedback_responses_details` WHERE job_feedback_response_id IN ( SELECT id FROM `job_feedback_responses` WHERE `job_candidate_id`=".$get['job_candidate_id']." AND `job_selection_process_step_id`=".$get['job_selection_process_step_id']." AND is_active =0) And is_active=0";
		$respon = $callConfig->getAllRows($query);
		$deta['survey_details']=$details;
		$deta['question']=$question;
		$deta['response']=$respon;
		return $deta;
	}	
	function getListJobPostingsList($data){
		global $callConfig;
		$return = array();
		$condition ="";
		if($data['start_date']!="" AND $data['end_date']!=""){
			$condition .= " AND jp.requested_date >='".$data['start_date']."' and jp.requested_date <='".$data['end_date']."'";
		}else{
			$condition .= " AND jp.requested_date >='".date('Y-m-d', strtotime('first day of this month'))."' and jp.requested_date <='".date('Y-m-d', strtotime('last day of this month'))."'";
		}
		if($data['department']!=""){
			$condition .= " AND jp.department_id ='".$data['department']."'";
		}
		if($data['location']!=""){
			$condition .= " AND jp.location_id ='".$data['location']."'";

		}
		$sql = "SELECT *, jp.id as jpid FROM `job_postings` jp LEFT JOIN job_titles jt on jp.job_code = jt.id where jp.is_active = '0' AND jp.company_id = '".$data['company_id']."' ".$condition;
		$datas = $callConfig->getAllRows($sql);
		$shortlistcnt = 0;
		$totalcandidet = 0;
		foreach($datas as $list){
			$sql1 ="SELECT count(id) as cnt FROM `job_posting_candidates` WHERE is_active = '0' and company_id = '".$data['company_id']."' and job_posting_id =".$list->jpid;
			$row = $callConfig->getRow($sql1);
			$sql33 = "SELECT count(id) as cnt FROM `job_posting_candidates` where is_active = 0 AND company_id = '".$data['company_id']."' and job_posting_id =".$list->jpid." and shortlisted = '0'";
			$shortlisted = $callConfig->getRow($sql33);
			$sql45 = "SELECT count(id) as cnt FROM `job_posting_candidates` where is_active = 0 AND company_id = '".$data['company_id']."' and job_posting_id =".$list->jpid." and current_status in('58','59') and shortlisted = '0'";
			$offerrelised = $callConfig->getRow($sql45);
			$sql45 = "SELECT count(id) as cnt FROM `job_posting_candidates` where is_active = 0 AND company_id = '".$data['company_id']."' and job_posting_id =".$list->jpid." and current_status = '59' and shortlisted = '0'";
			$offeraccept = $callConfig->getRow($sql45);
			$in_porccess_array = array();
			$sql55 ="SELECT * FROM `job_posting_candidates` WHERE is_active = '0' and company_id = '".$data['company_id']."' and job_posting_id =".$list->jpid." AND shortlisted = '0' AND current_status NOT IN('58','59')";
			$rowss = $callConfig->getAllRows($sql55);
			foreach ($rowss as $value) {
				$sql88 ="SELECT jsps.select_name, count(jc.id) as cnt FROM job_posting_candidates jc left JOIN `job_selection_process_steps` jsps on jc.job_selection_process_step_id = jsps.id WHERE jsps.id ='".$value->job_selection_process_step_id."' and jc.shortlisted =0 and jc.job_posting_id ='".$list->jpid."'";
				$row88 = $callConfig->getRow($sql88);
				$in_porccess_array[] =array("name"=>$row88->select_name,'cnt'=>$row88->cnt);
			}
			$totalcandidet = $totalcandidet+$row->cnt;
			$return['list'][] = array('id'=>$list->jpid,'title' => $list->job_title,'requested_date' => $list->requested_date,'job_desc' => $list->job_desc
				,'total_candidate' => $row->cnt,'shortlistcnt' => $shortlisted->cnt,'notshortlistcnt'=>$notshortlistcnt,'offeraccepted'=>$offeraccept->cnt,'offerrelesed'=>$offerrelised->cnt,'in_preccess'=>count($rowss),'in_procees_list'=>$in_porccess_array);
		}
		$return['totaljob']= count($datas);
		$return['totalcndided']= $totalcandidet;
		return $return;
	}
