	}elseif($workflow->after_rejection_email !="" AND $type ="reject"){
		$emailcontain_id = $workflow->after_rejection_email;
		$emailtype = $workflow->send_rejection_email_to;
		$sendstatus =0;
	}
	if($sendstatus =='0'){
