function checkLeaveApplicable($data){
	global $callConfig;
	$todaydate = date('d-m-Y');
	$year = date('Y');
	$resultreturn  =array();
	$leavetypesql = "SELECT * FROM `leave_types` where company_id = '".$data['company_id']."' and is_active = 0";
	$leaevtyperesults = $callConfig->getAllRows($leavetypesql);
	foreach($leaevtyperesults as $leaevtyperesult){
		$condition = "";
		$employee_filter = json_decode($leaevtyperesult->employee_filter,1);
		$resultreturn['employee_filter'][] = $employee_filter;
		if($employee_filter !=""){   // filter availbale or not 
			$leave_type_levels = "SELECT * FROM `leave_type_levels` where is_active='0' and company_id = '".$data['company_id']."' and leave_type_id='".$leaevtyperesult->id."'";
			$leave_type_levels = $callConfig->getRow($leave_type_levels);
$jsoncontain = $leaevtyperesult->employee_filter;
$decodejsoncontain = json_decode($jsoncontain,1);
foreach($decodejsoncontain as $keys=>$vale){
	$st = "";
	foreach($vale as $keym=>$vs){
		$st .= $keym.",";
	}
	$st =rtrim($st, ", ");
	$condition .= ' AND '.$keys.'  IN ('.$st.')';
}
// $condition .= $employee_filter['department_id']==""?"":' AND department_id = "'.$employee_filter['department_id'].'"';
// $condition .= $employee_filter['designation_id']==""?"":' AND designation_id = "'.$employee_filter['designation_id'].'"';
// $condition .= $employee_filter['gender']==""?"":' AND gender = "'.$employee_filter['gender'].'"';
// $condition .= $employee_filter['employee_type']==""?"":' AND employee_type = "'.$employee_filter['employee_type'].'"';	
$employee_detailsurl = "select * FROM employees where is_active='0' and company_id = '".$data['company_id']."'".$condition;
//echo "</br></br></br>";
			$resultreturn['employee_detailsurl'][] = $employee_detailsurl;
			$employee_details = $callConfig->getAllRows($employee_detailsurl);
			foreach($employee_details as $employee_detail){
			//	print_r($employee_detail);
				if($leave_type_levels->before_or_after=="B"){$before_or_after  = "-";}else{$before_or_after = "+"; }
				if($leave_type_levels->action_frequency  == 'W'){$startleavetype = "week";}elseif($leave_type_levels->action_frequency  == 'M'){$startleavetype = "months"; }elseif($leave_type_levels->action_frequency  == 'Y'){ 	$startleavetype = "years"; }else{ 	$startleavetype = "days"; }
				$leavestart = strtotime($employee_detail->joining_date. ' '.$before_or_after.' '.round($leave_type_levels->action_number).' '.$startleavetype);
				$resultreturn['leave_start_date'][] = $leavestart;
				if($leavestart <= strtotime(date('d-m-Y'))){
					$resultreturn['leave_start_date'][] = "Yes";
					$emp_leave_balances = "select * FROM emp_leave_balances where is_active='0' and company_id = '".$data['company_id']."' AND employee_id = '".$employee_detail->id."' AND leave_type = '".$leaevtyperesult->id."'";
					$emp_leave_balancesresults = $callConfig->getRow($emp_leave_balances);
					if(!isset($emp_leave_balancesresults->id)){
						$applicable_leaves_balance = $emp_leave_balancesresults->applicable_leaves;	
						$limitleave = $leave_type_levels->max_accured_limit;
						if($emp_leave_balancesresults->first_accrual == 'P'){
							$base_onleave = $leave_type_levels->base_on;
							$addedleave = $applicable_leaves_balance + $base_onleave;
						}else{
							$week = $leave_type_levels->base_on * 52;
							$month = $leave_type_levels->base_on * 12;
							$years = $leave_type_levels->base_on * 1;
							$days =  $leave_type_levels->base_on * ((strtotime($todaydate. ' + 1 years') - strtotime($todaydate)) / (60 * 60 * 24));
							if($leave_type_levels->accured_action_based  == 'W'){ $addedleave=$week;  }elseif($leave_type_levels->accured_action_based  == 'M'){$addedleave=$month;  }elseif($leave_type_levels->accured_action_based  == 'Y'){ 	$addedleave=$years; }else{ 	$addedleave=$days; }
						}
						if($leaevtyperesult->accruals_happen == 'B'){
							$addedleaveok = $addedleave; 
						}else{
							$addedleaveok = '0';
						}
						if($addedleaveok <= $limitleave){ 
							$fieldnames = array('is_active'=>'0','company_id'=>$data['company_id'],'employee_id'=>$employee_detail->id,'leave_type'=>$leaevtyperesult->id,'applicable_leaves'=>$addedleaveok,'consumed_leaves'=>'0','current_status'=>'0','leave_year'=>$year);
							$res1=$callConfig->insertRecord('emp_leave_balances',$fieldnames);
							$fieldnames['transaction_date'] = date('Y-m-d');
							$insertnewbalance=$callConfig->insertRecord('emp_leave_allocations',$fieldnames);
						}else{
							$fieldnames = array('is_active'=>'0','company_id'=>$data['company_id'],'employee_id'=>$employee_detail->id,'leave_type'=>$leaevtyperesult->id,'applicable_leaves'=>$limitleave,'consumed_leaves'=>'0','current_status'=>'0','leave_year'=>$year);
							$res1=$callConfig->insertRecord('emp_leave_balances',$fieldnames);
							$fieldnames['transaction_date'] = date('Y-m-d');
							$insertnewbalance=$callConfig->insertRecord('emp_leave_allocations',$fieldnames);
						}
					}
				}else{
					$resultreturn['leave_start_date'][] = "NO";
				}
			}
		}else{
			$resultreturn['allocation'][] = "NO";
			
		}
		$rettt[] = $resultreturn;
	}
return $rettt;
}
function cronJobLeave($data){
	global $callConfig;
	$this->checkLeaveApplicable($data);
	$todaydate = date('d-m-Y');
	$year = date('Y');
//	echo "<pre>";
	$emp_leave_balancesurl = "select elb.id as elbid,elb.employee_id as employee_id,elb.leave_type as elbleave_type,elb.applicable_leaves,elb.consumed_leaves,elb.leave_year,elb.weekend_leave_consume,elb.holiday_leave_consume,elb.employee_id,elb.status_date as elb_status_date,lt.* FROM emp_leave_balances elb LEFT JOIN leave_types lt on elb.leave_type = lt.id  where elb.is_active='0' and elb.company_id = '".$data['company_id']."'";
	$emp_leave_balances = $callConfig->getAllRows($emp_leave_balancesurl);
	foreach($emp_leave_balances as $emp_leave_balancess){ 
		$returnresultarray = array();
		$lastupdatesql = "SELECT * FROM `emp_leave_allocations` where company_id = '".$data['company_id']."' and employee_id ='".$emp_leave_balancess->employee_id."' and  leave_type= '".$emp_leave_balancess->elbleave_type."' ORDER BY transaction_date DESC";  
		$lastupdateresult = $callConfig->getRow($lastupdatesql);

		$leave_type_levels = "SELECT * FROM `leave_type_levels` where is_active='0' and company_id = '".$data['company_id']."' and leave_type_id='".$emp_leave_balancess->id."'";
		$leave_type_levels = $callConfig->getRow($leave_type_levels);

		$employee_detailsurl = "select * FROM employees where is_active='0' and company_id = '".$data['company_id']."' and id='".$emp_leave_balancess->employee_id."'";
		$employee_details = $callConfig->getRow($employee_detailsurl);

		if($leave_type_levels->before_or_after=="B"){$before_or_after  = "-";}else{$before_or_after = "+"; }
		if($leave_type_levels->action_frequency  == 'W'){$startleavetype = "week";}elseif($leave_type_levels->action_frequency  == 'M'){$startleavetype = "months"; }elseif($leave_type_levels->action_frequency  == 'Y'){ 	$startleavetype = "years"; }else{ 	$startleavetype = "days"; }
		$leavestart = strtotime($employee_details->joining_date. ' '.$before_or_after.' '.round($leave_type_levels->action_number).' '.$startleavetype);
// End Accrual Schedule start day to leave
		$returnresultarray['employe_id'] = $emp_leave_balancess->employee_id;
		$returnresultarray['leave_type'] = $emp_leave_balancess->elbleave_type;
		$returnresultarray['leave_start_date'] = date('d-m-Y',$leavestart);
		$returnresultarray['leave_today_date'] = $todaydate;
		if($leavestart <= strtotime(date('d-m-Y'))){
			$returnresultarray['leave_start_date_working'] = "ok";
			if(isset($lastupdateresult->id)){
				$lastupdatedate = $lastupdateresult->transaction_date;
				$returnresultarray['lastupdatedate'] = $lastupdatedate;

			}else{
				$lastupdatedate = $emp_leave_balancess->elb_status_date;
				$returnresultarray['lastupdatedate'] = $lastupdatedate;
			}

			if($leave_type_levels->accured_action_based  == 'W'){ $accruedaddtype = "week"; }elseif($leave_type_levels->accured_action_based  == 'M'){$accruedaddtype = "months"; }elseif($leave_type_levels->accured_action_based  == 'Y'){ 	$accruedaddtype = "years"; }else{ 	$accruedaddtype = "days"; }
			$returnresultarray['increment_days'] = $leave_type_levels->base_on;
	$statusupdatedatetodayornot = strtotime($lastupdatedate. ' + 1 '.$accruedaddtype);  //increment days in date
	$statusupdatedatetodayornots = date('d-m-Y',$statusupdatedatetodayornot);
	$returnresultarray['statusupdatedatetodayornots'] = $statusupdatedatetodayornots;
	if($statusupdatedatetodayornots == $todaydate){   //status date Same or Not 
		$returnresultarray['samedate'] = "ok";
		$applicable_leaves_balance = $emp_leave_balancess->applicable_leaves;	
		$limitleave = $leave_type_levels->max_accured_limit;
		if($emp_leave_balancess->first_accrual == 'P'){
			$base_onleave = $leave_type_levels->base_on;
			$addedleave = $applicable_leaves_balance + $base_onleave;
		}else{
			$week = $leave_type_levels->base_on * 52;
			$month = $leave_type_levels->base_on * 12;
			$years = $leave_type_levels->base_on * 1;
			$days =  $leave_type_levels->base_on * ((strtotime($todaydate. ' + 1 years') - strtotime($todaydate)) / (60 * 60 * 24));
			if($leave_type_levels->accured_action_based  == 'W'){ $addedleave=$week;  }elseif($leave_type_levels->accured_action_based  == 'M'){$addedleave=$month;  }elseif($leave_type_levels->accured_action_based  == 'Y'){ 	$addedleave=$years; }else{ 	$addedleave=$days; }
		}
		$returnresultarray['addedleave'] = $addedleave;

		$penddingleave = $emp_leave_balancess->applicable_leaves - $emp_leave_balancess->consumed_leaves;
		$penddingleavepercentage  = $emp_leave_balancess->applicable_leaves - $emp_leave_balancess->consumed_leaves;

		$carryovertype = $leave_type_levels->carry_over_limit;
		$percentagecarryoverleave = ($carryovertype / 100)*$emp_leave_balancess->applicable_leaves;				
		if($leave_type_levels->carry_over_limit_type == 'P'){
			$halfdaycalculation = round($percentagecarryoverleave / 5, 1) * 5;
			$penddingleave = $halfdaycalculation;
		}
		$carryoverleave = 0;
		if($carryovertype == 'N' ||  $carryovertype == ''){
			$carryoverleave = 0;
		}elseif($carryovertype == 'U'){
			$carryoverleave = $penddingleave;
		}else{
			if($penddingleave <= $carryovertype){
				$carryoverleave = $penddingleave;
			}else{
				$carryoverleave = $carryovertype;
			}
		}

	if($addedleave <= $limitleave){   //leave max added or Not. 
			//carry_over_limit_type
		if($leave_type_levels->accured_action_based == 'Y'){  //yearly new entry added emp_leave_balances table
			$fields = array('is_active' =>'1','status_date'=>date('Y-m-d'));
			$whrcon = "id='".$emp_leave_balancess->elbid."'";
			$res1 = $callConfig->updateRecord('emp_leave_balances',$fields,'','',$whrcon);
			$fieldnames = array('is_active'=>'0','company_id'=>$data['company_id'],'employee_id'=>$emp_leave_balancess->employee_id,'leave_type'=>$emp_leave_balancess->elbleave_type,'applicable_leaves'=>$carryoverleave,'consumed_leaves'=>'0','current_status'=>'0','leave_year'=>$year);
			$insertnewbalance=$callConfig->insertRecord('emp_leave_balances',$fieldnames);
			$fieldnames['transaction_date'] = date('Y-m-d');
			$insertnewbalance=$callConfig->insertRecord('emp_leave_allocations',$fieldnames);

		}else{	//Not yearly Update record emp_leave_balances table

			$fields = array('leave_year' =>$year,'is_active' =>'0','applicable_leaves'=>$addedleave);
			$whrcon = "id='".$emp_leave_balancess->elbid."'";
			$res1 = $callConfig->updateRecord('emp_leave_balances',$fields,'','',$whrcon);
			$fieldnames = array('is_active'=>'0','company_id'=>$data['company_id'],'employee_id'=>$emp_leave_balancess->employee_id,'leave_type'=>$emp_leave_balancess->elbleave_type,'applicable_leaves'=>$addedleave,'consumed_leaves'=>'0','current_status'=>'0','leave_year'=>$year);
			$fieldnames['transaction_date'] = date('Y-m-d');
			$insertnewbalance=$callConfig->insertRecord('emp_leave_allocations',$fieldnames);
		}

	}else{  //Not Limit Outside this part work emp_leave_balances table
		
		if($leave_type_levels->accured_action_based == 'Y'){  //yearly new entry added emp_leave_balances table
			$fields = array('is_active' =>'1','status_date'=>date('Y-m-d'));
			$whrcon = "id='".$emp_leave_balancess->elbid."'";
			$res1 = $callConfig->updateRecord('emp_leave_balances',$fields,'','',$whrcon);
			$returnresultarray['limitexitempleaveupdate'] = $res1;

			$fieldnames = array('is_active'=>'0','company_id'=>$data['company_id'],'employee_id'=>$emp_leave_balancess->employee_id,'leave_type'=>$emp_leave_balancess->elbleave_type,'applicable_leaves'=>$carryoverleave,'consumed_leaves'=>'0','current_status'=>'0','leave_year'=>$year);
			$insertnewbalance=$callConfig->insertRecord('emp_leave_balances',$fieldnames);
			$fieldnames['transaction_date'] = date('Y-m-d');
			$callConfig->insertRecord('emp_leave_allocations',$fieldnames);

		}else{	//Not yearly Update record emp_leave_balances table

			$fields = array('leave_year' =>$year,'is_active' =>'0','applicable_leaves'=>$limitleave);
			$whrcon = "id='".$emp_leave_balancess->elbid."'";
			$res1 = $callConfig->updateRecord('emp_leave_balances',$fields,'','',$whrcon);
			$returnresultarray['limitexitempleaveupdate'] = $res1;
			$fieldnames = array('is_active'=>'0','company_id'=>$data['company_id'],'employee_id'=>$emp_leave_balancess->employee_id,'leave_type'=>$emp_leave_balancess->elbleave_type,'applicable_leaves'=>$limitleave,'consumed_leaves'=>'0','current_status'=>'0','leave_year'=>$year);
			$fieldnames['transaction_date'] = date('Y-m-d');
			$insertnewbalance=$callConfig->insertRecord('emp_leave_allocations',$fieldnames);
			$returnresultarray['limitexitempleave'] = $insertnewbalance;
		}
	}
}else{
	$returnresultarray['samedate'] = "NO";
}
}else{
	$returnresultarray['leave_start_date_working'] = "NO";
}
$rsrrs[] = $returnresultarray;
}
return $rsrrs;
}
function checkLeaveBalanceOrHalfDay($data){
	global $callConfig;
	$balancearray = array();
	$halfdaysql = "SELECT eb.id,lt.half_day,eb.applicable_leaves,eb.consumed_leaves FROM emp_leave_balances eb, `leave_types` lt  WHERE  eb.is_active='0' and eb.company_id = '".$data['company_id']."' AND eb.leave_type = lt.id  AND eb.employee_id = '".$data['emp_id']."' AND lt.leave_category_id = '".$data['categorytype']."' AND eb.leave_year = '".$data['leave_year']."'";

	//$halfdaysql = "select lt.half_day FROM emp_leave_balances elb LEFT JOIN leave_types lt on elb.leave_type = lt.id  where elb.is_active='0' and elb.company_id = '".$data['company_id']."' and elb.employee_id='".$data['emp_id']."' and lt.leave_category_id='".$data['categorytype']."'";
	$halfdya = $callConfig->getRow($halfdaysql);
	$leavedetails = array("halfday"=>$halfdya->half_day,'consumed_leaves'=>$halfdya->consumed_leaves,'applicable_leaves'=>$halfdya->applicable_leaves,'weekend_leave_consume'=>$halfdya->weekend_leave_consume,'holiday_leave_consume'=>$halfdya->holiday_leave_consume,'id'=>$halfdya->id);

	$tempcheckleavesql = "SELECT sum(leave_days) as leave_days FROM `temp_attendance_details` WHERE company_id = '".$data['company_id']."' and is_active = 0 AND MONTH(attendance_date) = '".$data['month']."' AND YEAR(attendance_date) = '".$data['leave_year']."' AND attendance_type = 2 AND leave_type_id = '".$data['categorytype']."' AND employee_id = '".$data['emp_id']."'";
	$tempcheckleave = $callConfig->getRow($tempcheckleavesql);

	$emp_leave_balancesurl = "select elb.applicable_leaves,elb.consumed_leaves,lt.half_day,elb.weekend_leave_consume,elb.holiday_leave_consume,lc.id FROM emp_leave_balances elb LEFT JOIN leave_types lt on elb.leave_type = lt.id LEFT JOIN leave_categories lc on lt.leave_category_id = lc.id where elb.is_active='0' and elb.company_id = '".$data['company_id']."' and elb.employee_id='".$data['emp_id']."' group By leave_type";
	$emp_leave_balance = $callConfig->getAllRows($emp_leave_balancesurl);
	foreach($emp_leave_balance as $emp_leave_balances){
		$balancearray[$emp_leave_balances->id] = array("applicable_leaves"=>$emp_leave_balances->applicable_leaves,"consumed_leaves"=>$emp_leave_balances->consumed_leaves,"weekend_leave_consume"=>$emp_leave_balances->weekend_leave_consume,"holiday_leave_consume"=>$emp_leave_balances->holiday_leave_consume);
	}
	//$returnarray['sql'] = $halfdaysql;
	$returnarray['leave_details'] = $leavedetails;
	$returnarray['balance'] = $balancearray;
	$returnarray['templeaves'] = $tempcheckleave->leave_days;	
	return $returnarray;
}
