			//print_r($res1dd);
			$this->emailSendWorkflow($data,$resutlworkflow,'approve');
		}
		$totupdate = $updateworkresponscnt->cnt+1;
		//$totupdate++;
		foreach($status as $key=>$statuse){
	if($totupdate==$key){   //match level
		if($resutlworkflow->approval_type == 'custom_process'){  //custom process only
			$addone = $key;
			$addone++;
			$conjson = json_decode($resutlworkflow->sub_approve_type,1);
			$inserttransactionapprovelog =array('company_id'=>$data['company_id'],'transaction_table'=>$data['table'],'transaction_id'=>$data['rid'],'response_type'=>'','user_id'=>$conjson['step_'.$addone],'request_date'=>date("Y-m-d H:i:s"),'workflow_id'=>$data['workflow_id'],'ref_field'=>$data['ids']);
			$resf=$callConfig->insertRecord("transaction_approval_logs",$inserttransactionapprovelog);
			$this->workflowsendnotifiction($resutlworkflow,$data,$conjson['step_'.$addone]);	

		}elseif($resutlworkflow->approval_type == 'role_levels'){
			$onepluselevel = $key;
			$onepluselevel++;
			$getuserid =$this->rolelevelworkflow($resutlworkflow,$data,$onepluselevel);
			$rrrr =$getuserid;
			$inserttransactionapprovelog =array('company_id'=>$data['company_id'],'transaction_table'=>$data['table'],'transaction_id'=>$data['rid'],'response_type'=>'','user_id'=>$getuserid,'request_date'=>date("Y-m-d H:i:s"),'workflow_id'=>$data['workflow_id'],'ref_field'=>$data['ids']);
			if($getuserid != "-1"){
				$resf=$callConfig->insertRecord("transaction_approval_logs",$inserttransactionapprovelog);
				$this->workflowsendnotifiction($resutlworkflow,$data,$getuserid);	
			}
		}else{   
			$hrurl = "SELECT reports_to FROM application_users WHERE id = '".$data['user_id']."'";
