			$resf=$callConfig->insertRecord("transaction_approval_logs",$inserttransactionapprovelog);	
			$this->workflowsendnotifiction($resutlworkflow,$data,$datareportid->reports_to);
		}
	}
}
}else{
	if($resutlworkflow->approval_type == 'email_groups' || $resutlworkflow->approval_type == 'access_levels' || $resutlworkflow->approval_type == 'buddy' || $resutlworkflow->approval_type == 'access_levels'){
		$totaltransaction = "select count(id) as cnt from transaction_approval_logs where transaction_table = '".$data['table']."' AND transaction_id='".$data['rid']."'";
		$restotaltransaction = $callConfig->getRow($totaltransaction);
		$min = ($resutlworkflow->minimum =="" || $resutlworkflow->minimum =='0')?$restotaltransaction->cnt:$resutlworkflow->minimum;
		if($min == $updateworkresponscnt->cnt){
			$st = $data['status']=='-1'?'30':$data['status'];
			$updatequery ="UPDATE ".$data['table']." SET current_status = ".$st." WHERE id IN(".$data['ids'].")";
			$res1dd = $callConfig->executeQuery($updatequery);
			$this->emailSendWorkflow($data,$resutlworkflow,'reject');
		}	
	}elseif($data['status'] !="-1"){
		$updatequery ="UPDATE ".$data['table']." SET current_status = ".$st." WHERE id IN(".$data['ids'].")";
		$res1dd = $callConfig->executeQuery($updatequery);
		$this->emailSendWorkflow($data,$resutlworkflow,'reject');
	}
}
return $res1dd;
