function checkAlreadyTransactionApprovalLogs($data,$checkcriteria,$row){
	global $callConfig;
	if($data['tablename']=="project_timesheets"){ $rids = explode(',',$data['rid']); $rid = $rids[0]; }else{ $rid = $data['rid']; }
	$already = "select * from transaction_approval_logs where transaction_table  = '".$checkcriteria['workflow_configuration']->process_type."' and transaction_id   = '".$rid."' and user_id  = '".$row['reports_to']."'  and company_id = '".$data['company_id']."' AND workflow_id = '".$checkcriteria['workflow_configuration']->id."'"; 
	$alreadydata = $callConfig->getRow($already);
	if(!isset($alreadydata->id)){
		$inserttransactionapprovelog =array('company_id'=>$data['company_id'],'transaction_table'=>$checkcriteria['workflow_configuration']->process_type,'transaction_id'=>$rid,'response_type'=>'','user_id'=>$row['reports_to'],'request_date'=>date("Y-m-d H:i:s"),'workflow_id'=>$checkcriteria['workflow_configuration']->id,'ref_field'=>$data['rid']);
		$statusincode = json_decode($checkcriteria['workflow_configuration']->approve_update_status);
		if($statusincode[0]->status !="" ||	$statusincode[0]->status !="-1"){
			$updatequery ="UPDATE ".$data['tablename']." SET current_status = ".$statusincode[0]->status." WHERE id IN(".$data['rid'].")";
			$res1 = $callConfig->executeQuery($updatequery);
		}
		$res=$callConfig->insertRecord("transaction_approval_logs",$inserttransactionapprovelog);
		$this->workflowsendnotifiction($checkcriteria,$data,$row['reports_to']);
	}	
	return $res;
}
function workflowsendnotifiction($checkcriteria,$data,$userarray){
	global $callConfig;
	if($data['tablename']=="project_timesheets"){ $rids = explode(',',$data['rid']); $rid = $rids[0]; }else{ $rid = $data['rid']; }
	$cretedby = "SELECT created_by FROM ".$data['tablename']." where is_active = 0 and company_id = '".$data['company_id']."' and id='".$rid."'";
