function getEmployeeWorkingEntrys($get){
	global $callConfig;
	$emp_list = json_decode($get['emplist'],1);
	$discrepancy = array();
	$month = $get['month'];
	$year = $get['year'];
	$retrunarray = array();
	if(empty($emp_list)){
		$query="SELECT id,display_name,image  FROM `employees` WHERE company_id = '".$get['company_id']."' and is_active =0";
	}else{
		$liemp =implode(",",$emp_list);
		$query="SELECT id,display_name,image  FROM `employees` WHERE company_id = '".$get['company_id']."' and is_active =0 AND id IN(".$liemp.")";
	}
	$empdatas = $callConfig->getAllRows($query);
	foreach ($empdatas as $value) {
		$empidlist[$value->id] = array('display_name'=>$value->display_name,'image'=>$value->image);
	}
	$attstc = "SELECT * FROM attendance_settings WHERE is_active=0 and company_id=".$get['company_id'];
	$atsdata = $callConfig->getRow($attstc);
	$workingdays = json_decode($atsdata->working_days,1);
	$shiftkeys = "SELECT * FROM attendance_key_types WHERE is_active=0 and company_id=".$get['company_id'];
	$shiftkeysdata = $callConfig->getAllRows($shiftkeys);
	foreach ($shiftkeysdata as $skey=>$svalue) {
		$shift[$svalue->key_short_code] = (array)$svalue;
	}
	$holidays = "SELECT holiday_date FROM holidays WHERE is_active=0 and company_id=".$get['company_id'];
	$holidaysdata = $callConfig->getAllRows($holidays);
	foreach ($holidaysdata as $hkey=>$hvalue) {
		$holidaysdatas[] = $hvalue->holiday_date;
	}
	$min_working_hours = explode(":", $atsdata->minimum_hours_required);
	$half_working_hours = explode(":", $atsdata->half_day_hours);
	$slctdate = date($get['monthstartday']."-".$get['month']."-".$get['year']);
	$startdate = date("Y-m-d",strtotime("-1 month", strtotime($slctdate)));
	$enddate = date("Y-m-d",strtotime('-1 day',strtotime($slctdate)));  
	$timeshetetrys = array();
	$i = 0;
	foreach($empidlist as $ky => $emp){
		$start = new DateTime($startdate);
		$end = new DateTime($enddate);
		$dates = array();
		$timeshettempoyee = array();
		$sql = "SELECT GROUP_CONCAT(id SEPARATOR ',') AS id,timesheet_date,SUM(billable_hrs) as billable_hrs,emp_id FROM `project_timesheets` WHERE company_id = '".$get['company_id']."' and is_active = 0 and emp_id = '".$ky."' and timesheet_date >= '".$startdate."' and timesheet_date <= '".$enddate."' GROUP BY timesheet_date,emp_id";
		$timesheets = $callConfig->getAllRows($sql);
		foreach($timesheets as $timesheet){
			if($timesheet->billable_hrs > '0'){
				if($timesheet->billable_hrs < $min_working_hours[0]){
					$discrepancy[$ky] = $ky;
				}
				$timeshettempoyee[$timesheet->timesheet_date] = array("id"=>$timesheet->id,"timesheet_date"=>$timesheet->timesheet_date,"billable_hrs"=>$timesheet->billable_hrs,"emp_id"=>$timesheet->emp_id);
			}
		}
		while($start <= $end){
			$date = $start->format('Y-m-d');
			$dy = $start->format('l');
			if(in_array($date,$holidaysdatas)){
				$dates[$date] = array('day'=>'H','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['H']['color_code']);
			}elseif(!in_array($dy, $workingdays)){
				$dates[$date] = array('day'=>'O','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['O']['color_code']);
			}elseif(isset($timeshettempoyee[$date])){
				$dates[$date] = array('day'=>'W','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['W']['color_code']);
			}else{
				$leavesql = "SELECT el.employee_id,el.leave_type_id,lt.leave_type_name,el.leave_from,el.leave_to FROM `employee_leaves` el LEFT JOIN leave_types lt on el.leave_type_id = lt.id WHERE el.current_status = '".ST_APPROVED."' and el.employee_id = '".$ky."' and el.is_active=0 and el.company_id = '".$get['company_id']."' and  el.leave_from <= '".$date."' AND el.leave_to >= '".$date."'";
				$leavedata = $callConfig->getRow($leavesql);	
				if(isset($leavedata->leave_type_id)){
					if($leavedata->leave_type_id == '6'){
						$dates[$date] = array('day'=>'S','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['S']['color_code']);
					}else{
						$dates[$date] = array('day'=>'V','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['V']['color_code']);
					}
				}else{
					$dates[$date] = array('day'=>'A','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['A']['color_code']);
				}
			}
			if($i=='0'){
				$alldate[]  = $date; 
			}	
			$start->modify('+1 days');
			if($date == date("Y-m-d")){
				break;
			}
		}
		$timeshetetrys[$ky] = $dates;
		$i++;
	}
	$retrunarray['discrepancy'] = $discrepancy;
	$retrunarray['timesheet'] = $timeshetetrys;
	$retrunarray['date'] = $alldate;
	$retrunarray['emplist'] = $empidlist;
	$retrunarray['min_working_hours'] = $min_working_hours[0];
	$retrunarray['min_working_hours_full'] = $atsdata->minimum_hours_required;
	$retrunarray['half_working_hours'] = $half_working_hours[0];
	return $retrunarray;
}

