		$checkavlsql = "SELECT id FROM `payroll_steps` WHERE company_id = '".$post['company_id']."' AND category_id = '".$post['id']."' AND pay_year = '".$post['year']."' AND pay_month = '".$post['month']."'".$whrp;
		$check = $callConfig->getRow($checkavlsql);
		if(!isset($check->id)){
			$insert_array = array('company_id'=>$post['company_id'],'current_status'=>'0','is_active'=>'0','category_id'=>$post['id'],'pay_year'=>$post['year'],'pay_month'=>$post['month'],'pay_area_id' =>$post['pay_area_id']);
			$insert = $callConfig->insertRecord('payroll_steps',$insert_array);
			$ret['insert'] =$insert;
