			$userid = $userdetails->approval_manager;
		}else{
			$userid = $userdetails->reports_to;
		}
	$appv_fieldnames=array('company_id'=>$post['company_id'],'transaction_table'=>$post['table'],'transaction_id'=>$post['hid'],'user_id'=>$userid,'request_date'=>date("Y-m-d H:i:s"),'send_back_flag' => '0');
	$approval_id=$callConfig->insertRecord(TBL_TRANSACTION_APPROVAL_LOGS,$appv_fieldnames);

	$update_array_log = array('response_type '=>$post['status'],'response_date'=>date('Y-m-d H:i:s'));
	$where = "transaction_table = '".$post['table']."' AND transaction_id = '".$post['hid']."' AND user_id = '".$post['user_id']."'";
	$res=$callConfig->updateRecord(TBL_TRANSACTION_APPROVAL_LOGS,$update_array_log,"","",$where);

	$upadate_array = array('updated_by'=>$post['user_id'],'updated_date'=>date("Y-m-d H:i:s"),'current_status'=>$post['status']);
	$inserttasks = $callConfig->updateRecord('project_timesheets',$upadate_array,'id',$post['hid']);
	$ndcndfc['approval_id'] =  $approval_id;
	$ndcndfc['task'] =  $inserttasks;
	$msg = $post['table']." - ".$post['hid'];
	$user_ids  = array($userid);
	$option = "COM_INSERT_PROJECT_TIMESHEETS";
	$notdataa = array('company_id'=>$post['company_id'], 'id'=>$post['hid'],'notification_message'=>$msg, 'id'=>$post['hid'],'application_table_name'=>$post['table'], 'type'=>'ACTION', 'notification_users'=>$user_ids,'option'=>$option);
	$this->tosendnotifiations($notdataa);
	return $ndcndfc;
}
function getEmployeeCTCReports($get){
global $callConfig;
	$pay_year = $get['pay_year'];
	$pay_month = $get['pay_month'];
$sqql="SELECT emp.id,emp.emp_code,
CONCAT(emp.first_name,' ',COALESCE(emp.middle_name,''),' ' ,emp.last_name) 'Employee Name',
emp.joining_date 'DOJ',
(
SELECT dept.department_name
FROM departments dept
WHERE dept.id = emp.department_id
AND dept.company_id = emp.company_id
) 'Department',
(
SELECT de.designation_name
FROM designations de
WHERE de.id = emp.designation_id
AND de.company_id = emp.company_id
)'Designation',
(
SELECT loc.location_name
FROM locations loc
WHERE loc.id = emp.location_id
AND loc.company_id = emp.company_id
)'Location',
emp.email_id,
(
SELECT name
FROM earnings ear
WHERE ear.id = prsc.component_id
AND ear.company_id = prsc.company_id
)'name',
prs.total_no_of_days 'Total Days',
prs.total_no_of_leaves 'Leaves',
prs.total_lop_days 'LWPs',
prs.total_no_of_working_days 'Working Days',
IF(IFNULL( prs.total_lop_days,0) = prs.total_no_of_working_days , 0,  (prs.total_no_of_days - IFNULL( prs.total_lop_days,0))) 'Payable Days',
prsc.salary_component_standard,
prsc.salary_component_actual,
prsc.base_amount
FROM employees emp,
pay_run_summary prs,
pay_run_summary_components prsc
WHERE emp.id = prs.employee_id
AND emp.company_id = prs.company_id
AND prs.id = prsc.pay_run_summary_id
AND prs.company_id = prsc.company_id
AND prs.is_active = 0
AND prs.pay_year = '".$pay_year."' 
AND prs.pay_month = '".$pay_month."'
ORDER BY emp.joining_date,
emp.display_name";
$result = $callConfig->getAllRows($sqql);
$ret =array();
foreach($result as $results){
$ret1[] = $results->name;
$ret[$results->id][] = $results;
}
$return = array("componant"=>array_unique($ret1),"list"=>$ret);
return $return;
}



function togetPtAnualStatment($get){
	global $callConfig;
	$return = array();
 	$date1 = $get['start_year']."-".$get['start_month']."-01";
 	$date2 = $get['end_year']."-".$get['end_month']."-01";
	 $d1=new DateTime($date2); 
 	$d2=new DateTime($date1);                                  
 	$Months = $d2->diff($d1); 
 	$howeverManyMonths = (($Months->y) * 12) + ($Months->m);
	for($i=0;$i<=$howeverManyMonths;$i++){
		$datef = strtotime("+".$i." month", strtotime($date1));
		$year = date("Y",$datef);
		$month = date("m",$datef);
		$employee_list_query= "SELECT sum(salary_component_actual) sumpt,count(id) as emp FROM `pay_run_summary_components` WHERE pay_year = '".$year."' AND  pay_month = '".$month."'  AND is_active = 0 and company_id = '".$get['company_id']."' AND component_id = '".$get['component_id']."'";
		$employee_list = $callConfig->getAllRows($employee_list_query);
		$return['01-'.$month.'-'.$year] =  $employee_list;
	}
return $return;
}

