			$empidlist[$value->id] = array('display_name'=>$value->display_name,'image'=>$value->image,'emp_code'=>$value->emp_code);
		}
	}
	$attstc = "SELECT * FROM attendance_settings WHERE is_active=0 and company_id=".$get['company_id'];
