						$dates[$date] = array('day'=>'S','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['S']['color_code'],'display_value'=>$shift['S']['display_value'],'strthalfday'=>$leavesdetailsarray[$ky][$date]['start_half_day'],'endthalfday'=>$leavesdetailsarray[$ky][$date]['end_half_day'],'working_color'=>$shift['W']['color_code']);
						$discrepancy[$ky] = $emp;
					}else{
						$dates[$date] = array('day'=>'V','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['V']['color_code'],'display_value'=>$shift['V']['display_value'],'strthalfday'=>$tempdetailary[$ky][$date]['start_half_day'],'endthalfday'=>$tempdetailary[$ky][$date]['end_half_day'],'working_color'=>$shift['W']['color_code']);
						$discrepancy[$ky] = $emp;
					}
				}else{
					$dates[$date] = array('day'=>'A','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['A']['color_code'],'display_value'=>$shift['A']['display_value']);
					$discrepancy[$ky] = $emp;
				}
			}
			if($i=='0'){
				$alldate[]  = $date; 
			}	
			$start->modify('+1 days');
			// if($date == date("Y-m-d")){
			// 	break;
			// }
		}
}else{
	$retrunarray['valuedisplaytype'] = "insert";
		while($start <= $end){
			$date = $start->format('Y-m-d');
			$dy = $start->format('l');
			if(in_array($date,$holidaysdatas)){
				$dates[$date] = array('day'=>'H','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['H']['color_code'],'display_value'=>$shift['H']['display_value']);
			}elseif((!in_array($dy, $workingdays) AND $shift_check == '0') OR (!in_array($dy, $emp_shift_days) AND $shift_check == '1')){
				$dates[$date] = array('day'=>'O','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['O']['color_code'],'display_value'=>$shift['O']['display_value']);
			}elseif($tempdetailary[$ky][$date] !=""){
				$monthworkingdays++;
				
				if($tempdetailary[$ky][$date]['type']=="1"){
					$discrepancy[$ky] = $emp;
					$dates[$date] = array('day'=>'A','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['A']['color_code'],'display_value'=>$shift['A']['display_value']);
				}else{
					$actualworkingdays++;
					if($tempdetailary[$ky][$date]['leave_type_id']=="6"){
						$discrepancy[$ky] = $emp;
						$dates[$date] = array('day'=>'S','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['S']['color_code'],'display_value'=>$shift['S']['display_value'],'strthalfday'=>$tempdetailary[$ky][$date]['start_half_day'],'endthalfday'=>$tempdetailary[$ky][$date]['end_half_day'],'working_color'=>$shift['W']['color_code']);
					}else{
						$discrepancy[$ky] = $emp;
						$dates[$date] = array('day'=>'V','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['V']['color_code'],'display_value'=>$shift['V']['display_value'],'strthalfday'=>$tempdetailary[$ky][$date]['start_half_day'],'endthalfday'=>$tempdetailary[$ky][$date]['end_half_day'],'working_color'=>$shift['W']['color_code']);
					}	
				}
			}else{
				$monthworkingdays++;
				$actualworkingdays++;
				$dates[$date] = array('day'=>'W','date'=>$date,'billable_hrs'=>$timeshettempoyee[$date]['billable_hrs'],'timesheetid'=>$timeshettempoyee[$date]['id'],'color_code'=>$shift['W']['color_code'],'display_value'=>$shift['W']['display_value']);
			}
			if($i=='0'){
				$alldate[]  = $date; 
			}	
			$start->modify('+1 days');
		}
}
		$timeshetetrys[$ky] = $dates;
		$i++;
		$monthworkignday[$ky] = $monthworkingdays;
		$actualworkingday[$ky] = $actualworkingdays;
	}
	$retrunarray['shifts'] = $shiftcatres;
	$retrunarray['monthworkingdays'] = $monthworkignday;
	$retrunarray['actualworkingdays'] = $actualworkingday;
	$retrunarray['discrepancy'] = $discrepancy;
	$retrunarray['timesheet'] = $timeshetetrys;
	$retrunarray['date'] = $alldate;
	$retrunarray['emplist'] = $empidlist;
	$retrunarray['attendacnearray'] = $attendacnearray;
	$retrunarray['query']=$query;
	//$retrunarray['min_working_hours'] = $min_working_hours[0];
	//$retrunarray['min_working_hours_full'] = $atsdata->minimum_hours_required;
	//$retrunarray['half_working_hours'] = $half_working_hours[0];
	//echo "<pre>"; print_r($retrunarray);
	return $retrunarray;
}






