function getEmployeeTickets($data){
	global $callConfig;	
	$returnresul = array();
	$condition = "";
	if($data['emp_id']!=""){  $condition .= " AND emp_id = '".$data['emp_id']."'"; }
	if($data['priority']!=""){ $condition .=  " AND priority = '".$data['priority']."'";  }
	if($data['current_status']!="" AND isset($data['current_status'])){ $condition .=  " AND current_status = '".$data['current_status']."'"; }
	if($data['filterfromdate']!="" AND $data['filtertodate']!=""){ $condition .=  " and created_date >= '".$data['filterfromdate']."' and created_date <= '".$data['filtertodate']."'"; }
	if($data['field']!="" AND $data['user_id']!=""){ 
		$condition .=  " AND ".$data['field']." = '".$data['user_id']."'";
	}
	if($data['notdisplaycurrent_status']!=""){ 
		$condition .=  " AND (current_status  >'".$data['notdisplaycurrent_status']."' OR created_by= '".$data['user_id']."')";
	}
	$query2 = "SELECT * FROM project_tasks WHERE is_active=0 AND company_id = '".$data['company_id']."' ".$condition;
	$res = $callConfig->getAllRows($query2);
	$returnresul['tickets'] = $res;
	$dashboardsql = "SELECT id,task_name,current_status FROM project_tasks WHERE is_active=0 AND company_id = '".$data['company_id']."'";
	$dashboardres = $callConfig->getAllRows($dashboardsql);
	$returnresul['dashboard'] = $dashboardres;
	return $returnresul;
}
