	$res = $callConfig->getRow($query2);
	$retresult['tasklist'] = $res;
	$employeesql = "SELECT id,display_name,image FROM employees WHERE is_active=0 AND company_id = '".$data['company_id']."' AND id='".$res->emp_id."'";
	$employeeres = $callConfig->getRow($employeesql);
	$retresult['employee'] = $employeeres;
	$usersql = "SELECT id,display_name,user_photo FROM application_users WHERE is_active=0 AND company_id = '".$data['company_id']."' AND id='".$res->client_id."'";
	$userres = $callConfig->getRow($usersql);
	$retresult['users'] = $userres;
	$attachmentsql = "SELECT id,file_name,actual_file_name FROM application_attachments WHERE is_active=0 AND company_id = '".$data['company_id']."' AND application_table_name='project_tasks' AND transaction_id='".$data['id']."'";
	$attachmentres = $callConfig->getAllRows($attachmentsql);
	$retresult['application_attachments'] = $attachmentres;
	$projecttasklogssql = "SELECT id,project_task_id,emp_id,description,created_date FROM project_task_logs WHERE is_active=0 AND company_id = '".$data['company_id']."' AND project_task_id='".$data['id']."'";
	$projecttasklogsres = $callConfig->getAllRows($projecttasklogssql);
	foreach($projecttasklogsres as $projecttasklogsre){
		$logs['logsdetails'][$projecttasklogsre->id] = $projecttasklogsre;
		$attachmentsqls = "SELECT id,file_name,actual_file_name FROM application_attachments WHERE is_active=0 AND company_id = '".$data['company_id']."' AND application_table_name='project_task_logs' AND transaction_id='".$projecttasklogsre->id."'";
		$attachmentress = $callConfig->getAllRows($attachmentsqls);
		$logs['attachment'][$projecttasklogsre->id] = $attachmentress;

	}
	$retresult['logs'] = $logs;
		return $retresult;
}
