	 function getheadcountreportEmployeFilter11($get){
    	global $callConfig;
		$returnarray = array();
    	$year = $get['year'];
    	$monthNo = $get['month'];
    	$prev_year = $year-1;
    	$appendcondtion = '';
    	$filterdata = urldecode($get['filterby']);
    	$filters = json_decode($filterdata,1);
    	$curentyear_totalheadcount = 0;
    	$prevyear_totalheadcount = 0;
    	if($filters!=''){
    		$appendcondtion = " and ";
    		foreach ($filters as $filterkey => $filtervalue) {
    			$appendcondtion .= $filterkey ." IN ( ";
    			$appendcondtion .=  implode(',', array_keys($filtervalue));
    			$appendcondtion .=  " ) and ";
    		}
    		$appendcondtion = substr($appendcondtion, 0, -4);
    	}
    	for($i=1; $i<=12; $i++){
    		$fdate= $prev_year."-".sprintf('%02s', $i)."-01";
    		$ldate= $prev_year."-".sprintf('%02s', $i)."-31";
			 //$ldate= date('Y-m-d',strtotime($ldate));
			//$query="SELECT count(id) as headcount  FROM `employees` WHERE MONTH(joining_date)='".$i."' and YEAR(joining_date)='".$prev_year."' and company_id='".$get['company_id']."' and is_active =0".$appendcondtion;
			//$query="SELECT count(id) as headcount FROM `employees` WHERE (joining_date<='".$fdate."' and date_of_leaving >='".$fdate."') or date_of_leaving ='0000-00-00'".$appendcondtion;
    		$query="SELECT count(id) as headcount from (SELECT id,joining_date, if(date_of_leaving!='0000-00-00',date_of_leaving,'".$ldate."') as date_of_leaving  FROM `employees`) as td ";
		    //echo $query; //exit;
    		$returnarray['headcount'][]  = $query;
			$empdatas = $callConfig->getRow($query);
    		$query_emp="SELECT id,display_name,designation_id,department_id,joining_date,employment_category_id,location_id  FROM `employees`  WHERE company_id='".$get['company_id']."' AND employee_type =1 AND is_active =0  ".$appendcondtion;
    		$returnarray['employee'][]  = $query_emp;
			$emp_id_query = $callConfig->getAllRows($query_emp);
    		foreach ($emp_id_query as $eidvalue) {
    			$selected_employees[$eidvalue->id] = $eidvalue;
    		}
			//echo "<br>".$empdatas->headcount;
    		$prevyear_monthwise_headcount[$i]= $empdatas->headcount;
			//$prevyear_totalheadcount +=$empdatas->headcount;  
    	}
    	for($i=1; $i<=12; $i++){
    		if($i>$monthNo){
    			$curyear_monthwise_headcount[$i] = 0;
    		}else{
    			$fdate= $year."-".sprintf('%02s', $i)."-01";
    			$ldate= $year."-".sprintf('%02s', $i)."-31";
				//$query="SELECT count(id) as headcount  FROM `employees` WHERE MONTH(joining_date)='".$i."' and YEAR(joining_date)='".$year."' and company_id='".$get['company_id']."' and is_active =0".$appendcondtion;
				//$query="SELECT count(id) as headcount FROM `employees` WHERE (joining_date<='".$fdate."' and date_of_leaving >='".$fdate."') or date_of_leaving ='0000-00-00'".$appendcondtion;
    			$query="SELECT count(id) as headcount from (SELECT id,joining_date, if(date_of_leaving!='0000-00-00',date_of_leaving,'".$ldate."') as date_of_leaving  FROM `employees`) as td ";
    			$empdatas = $callConfig->getRow($query);
				$returnarray['headcount2'][]  = $query;
    			$query_emp="SELECT id,display_name,designation_id,department_id,joining_date,employment_category_id,location_id  FROM `employees` WHERE company_id='".$get['company_id']."' AND employee_type =1 AND is_active =0 ".$appendcondtion;
    			$returnarray['employee2'][]  = $query_emp;
				$emp_id_query = $callConfig->getAllRows($query_emp);
    			foreach ($emp_id_query as $eidvalue) {
    				$selected_employees[$eidvalue->id] = $eidvalue;
    			}
    			$curyear_monthwise_headcount[$i] = $empdatas->headcount;
				//$curentyear_totalheadcount +=$empdatas->headcount;  
    		}
    	}
		//print_r($prevyear_monthwise_headcount);print_r($curyear_monthwise_headcount); exit;
    	$details['years'] = array($year, $prev_year);
    	$details['curyear_monthwise_headcount'] = $curyear_monthwise_headcount;
    	$details['prevyear_monthwise_headcount'] = $prevyear_monthwise_headcount;
    	$details['Total_Head_Count'] = $curentyear_totalheadcount + $prevyear_totalheadcount;
    	$details['Total_Head_Count_CurrentYear'] = $curentyear_totalheadcount-$prevyear_totalheadcount;
    	//$details['Total_Head_Count_CurrentYear'] = $curentyear_totalheadcount;
    	$details['Total_Head_Count_PrevYear'] = $prevyear_totalheadcount;
    	$details['selected_employees'] = $selected_employees;
    	$query_1="SELECT *  FROM `employment_categories` WHERE company_id='".$get['company_id']."' and is_active =0";
    	$empdatas1 = $callConfig->getAllRows($query_1);
    	foreach ($empdatas1 as $value1) {
    		$query1="SELECT count(id) as headcount  FROM `employees` WHERE employment_category_id=".$value1->id." and company_id='".$get['company_id']."' and is_active =0";
    		$empresult = $callConfig->getRow($query1);
    		$empcategorywise_headcount[$value1->category_name] = $empresult->headcount;
    		$employment_category[$value1->id] = $value1->category_name;
    	}
    	$details['empcategorywise_headcount'] = $empcategorywise_headcount;
    	$query_2="SELECT *  FROM `divisions` WHERE company_id='".$get['company_id']."' and is_active =0";
    	$empdatas2 = $callConfig->getAllRows($query_2);
    	foreach ($empdatas2 as $valuediv) {
    		$divisions[$valuediv->id] = $valuediv->division_name;
    		$query_dept="SELECT *  FROM `departments` WHERE company_id='".$get['company_id']."' and is_active =0";
    		$deparmentsql = $callConfig->getAllRows($query_dept);
    		foreach ($deparmentsql as $value2) {
    			$query2="SELECT count(id) as headcount  FROM `employees` WHERE department_id=".$value2->id." and company_id='".$get['company_id']."' and is_active =0 and department_id in (select id from departments where division_id=".$valuediv->id.")";
    			$empresult = $callConfig->getRow($query2);
    			$divisionwise_headcount[$valuediv->id][$value2->department_name] = $empresult->headcount;
    		}
    	}
    	$details['division_list'] = $divisions;
    	$details['divisionwise_headcount'] = $divisionwise_headcount;
    	$query_3="SELECT *  FROM `locations` WHERE company_id='".$get['company_id']."' and is_active =0";
    	$empdatas3 = $callConfig->getAllRows($query_3);
    	foreach ($empdatas3 as $value3) {
    		$query3="SELECT count(id) as headcount  FROM `employees` WHERE location_id=".$value3->id." and company_id='".$get['company_id']."' and is_active =0";
    		$empresult = $callConfig->getRow($query3);
    		$locationwise_headcount[$value3->location_name] = $empresult->headcount;
    		$location[$value3->id] = $value3->location_name;
    	}
    	$details['locationwise_headcount'] = $locationwise_headcount;
    	$quer_4="SELECT *  FROM `departments` WHERE company_id='".$get['company_id']."' and is_active =0";
    	$empdatas4 = $callConfig->getAllRows($quer_4);
    	foreach ($empdatas4 as $value4) {
    		$query4="SELECT count(id) as headcount  FROM `employees` WHERE department_id=".$value4->id." and company_id='".$get['company_id']."' and is_active =0";
    		$empresult = $callConfig->getRow($query4);
    		$departmentwise_headcount[$value4->department_name] = $empresult->headcount;
    		$department[$value4->id] = $value4->department_name;
    	}
    	$details['departmentwise_headcount'] = $departmentwise_headcount;
    	$details['locations'] = $location;
    	$details['departments'] = $department;
    	$quer_5="SELECT *  FROM `designations` WHERE company_id='".$get['company_id']."' and is_active =0";
    	$empdatas5 = $callConfig->getAllRows($quer_5);
    	foreach ($empdatas5 as $value5) {
    		$designation[$value5->id] = $value5->designation_name;
    	}
    	$quer_6="SELECT *  FROM `job_titles` WHERE company_id='".$get['company_id']."' and is_active =0";
    	$empdatas6 = $callConfig->getAllRows($quer_6);
    	foreach ($empdatas6 as $value6) {
    		$jobtitles[$value6->id] = $value6->job_title;
    	}

    	$quer_7="SELECT *  FROM `cost_centers` WHERE company_id='".$get['company_id']."' and is_active =0";
    	$empdatas7 = $callConfig->getAllRows($quer_7);
    	foreach ($empdatas7 as $value7) {
    		$costcenter[$value7->id] = $value7->cost_center_name;
    	}

    	if(isset($get['fromdatetimesheet'])){
    		$quer_8="SELECT COUNT(DISTINCT timesheet_date) as cnt, emp_id FROM `project_timesheets` WHERE timesheet_date >= '".$get['fromdatetimesheet']."' and timesheet_date  <= '".$get['todatetimesheet']."' and is_active = 0 GROUP BY emp_id";
    	}else{
    		$startdate = date("Y-m-d", strtotime('monday this week', strtotime(date('Y-m-d'))));
    		$enddate = date("Y-m-d", strtotime('sunday this week', strtotime(date('Y-m-d'))));
    		$quer_8 = "SELECT COUNT(DISTINCT timesheet_date) as cnt, emp_id FROM `project_timesheets` WHERE timesheet_date >= '".$startdate."' and timesheet_date  <= '".$enddate."' and is_active = 0 GROUP BY emp_id";
    	}
    	$empdatas8 = $callConfig->getAllRows($quer_8);
    	foreach ($empdatas8 as $value8) {
    		$projecttimesheets[$value8->emp_id] = $value8->cnt;
    	}
    	$details['designations'] = $designation;
    	$details['employment_categories'] = $employment_category;
    	$details['job_titles'] = $jobtitles;
    	$details['costcenter'] = $costcenter;
    	$details['project_timesheets'] = $projecttimesheets; 

    	//  echo "<pre>"; print_r($details);
		//$returnarray['selected_employees'] = $selected_employees;
    	return $details;
    }
